INSERT INTO "grammar_topics" ("slug", "name", "group_name", "level", "sort_order", "summary", "lesson", "toeic_categories", "roadmap_labels", "updated_at") VALUES ('tu-loai', 'Từ loại: nhận diện qua hậu tố và vị trí', 'Từ loại', 'basic', 10, 'Chọn đúng danh từ, động từ, tính từ, trạng từ dựa vào vị trí trong câu và hậu tố.', '{"when_to_use":"Dạng câu Từ loại chiếm khoảng 1/3 Part 5. Bốn lựa chọn thường là cùng một gốc từ (success, successful, successfully, succeed). Bạn không cần hiểu hết nghĩa câu: chỉ cần xác định chỗ trống cần loại từ nào rồi nhìn hậu tố.","structure":"Vị trí quyết định loại từ:\n• Sau mạo từ (a/an/the), tính từ sở hữu (my, their…), giới từ → DANH TỪ.\n• Trước danh từ, sau động từ to be/become/seem → TÍNH TỪ.\n• Bổ nghĩa cho động từ, tính từ, cả câu; đứng giữa trợ động từ và động từ chính → TRẠNG TỪ.\n• Sau chủ ngữ, sau trợ động từ/động từ khuyết thiếu → ĐỘNG TỪ.\nHậu tố thường gặp: danh từ -tion, -ment, -ness, -ity, -ance/-ence, -er/-or (người); tính từ -ful, -less, -ive, -able/-ible, -al, -ous; trạng từ -ly; động từ -ize, -ify, -en.","examples":[{"en":"The company reported a significant increase in sales.","vi":"Công ty báo cáo doanh số tăng đáng kể. (tính từ trước danh từ)"},{"en":"Please complete the form carefully.","vi":"Vui lòng điền mẫu đơn cẩn thận. (trạng từ bổ nghĩa động từ)"},{"en":"Our main priority is customer satisfaction.","vi":"Ưu tiên chính là sự hài lòng của khách hàng. (danh từ sau tính từ sở hữu)"},{"en":"The new policy will simplify the approval process.","vi":"Chính sách mới sẽ đơn giản hóa quy trình duyệt. (động từ sau will)"}],"mistakes":[{"wrong":"She works very efficient.","right":"She works very efficiently.","note":"Bổ nghĩa cho động từ \"works\" phải là trạng từ."},{"wrong":"We need an accurately report.","right":"We need an accurate report.","note":"Trước danh từ là tính từ."},{"wrong":"The approve of the budget took a week.","right":"The approval of the budget took a week.","note":"Sau \"the\" cần danh từ."}],"signals":["Chỗ trống đứng giữa \"the/a/my\" và giới từ \"of\" → danh từ.","Chỗ trống đứng giữa \"is/are/was\" và danh từ không có → tính từ.","Câu đã đủ chủ ngữ + động từ + tân ngữ, chỗ trống ở cuối hoặc trước động từ → thường là trạng từ.","\"-ly\" gần như luôn là trạng từ; ngoại lệ hay gặp: friendly, costly, timely, likely (tính từ)."]}'::jsonb, ARRAY['word_form']::text[], ARRAY['Từ loại: nhận diện danh từ, động từ, tính từ, trạng từ qua hậu tố']::text[], now()) ON CONFLICT ("slug") DO NOTHING;
INSERT INTO "grammar_formulas" ("topic_id", "sort_order", "pattern", "usage", "examples", "updated_at") SELECT * FROM (VALUES
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'tu-loai'), 0, 'a/an/the/my/their + (adj) + NOUN', 'Sau mạo từ hoặc tính từ sở hữu là cụm danh từ.', '[{"en":"the final decision","vi":"quyết định cuối cùng"}]'::jsonb, now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'tu-loai'), 1, 'be/become/seem/remain + ADJ', 'Sau động từ nối là tính từ, không phải trạng từ.', '[{"en":"The results remain uncertain.","vi":"Kết quả vẫn chưa chắc chắn."}]'::jsonb, now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'tu-loai'), 2, 'S + V (+ O) + ADV  |  have/will + ADV + V', 'Trạng từ bổ nghĩa cho động từ, đứng cuối câu hoặc giữa trợ động từ và động từ chính.', '[{"en":"The team has recently expanded.","vi":"Nhóm gần đây đã mở rộng."}]'::jsonb, now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'tu-loai'), 3, 'ADV + ADJ + NOUN', 'Trạng từ đứng trước tính từ để bổ nghĩa cho tính từ.', '[{"en":"an extremely popular product","vi":"một sản phẩm cực kỳ được ưa chuộng"}]'::jsonb, now())
INSERT INTO "grammar_exercises" ("topic_id", "kind", "level", "prompt", "options", "answer_index", "accepted_answers", "explanation", "lesson_section", "updated_at") SELECT * FROM (VALUES
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'tu-loai'), 'choice', 'basic', 'The manager gave a very ___ presentation at the meeting.', ARRAY['inform', 'informative', 'informatively', 'information']::text[], 1::int, ARRAY[]::text[], 'Trước danh từ "presentation" và sau "very" cần tính từ: informative.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'tu-loai'), 'choice', 'basic', 'Please read the instructions ___ before using the machine.', ARRAY['careful', 'care', 'carefully', 'carefulness']::text[], 2::int, ARRAY[]::text[], 'Bổ nghĩa cho động từ "read" → trạng từ carefully.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'tu-loai'), 'choice', 'basic', 'The ___ of the new branch is scheduled for May.', ARRAY['open', 'opening', 'opened', 'opens']::text[], 1::int, ARRAY[]::text[], 'Sau "the" và trước "of" cần danh từ: opening.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'tu-loai'), 'choice', 'basic', 'All employees must ___ the safety guidelines.', ARRAY['follow', 'following', 'followed', 'follower']::text[], 0::int, ARRAY[]::text[], 'Sau động từ khuyết thiếu "must" là động từ nguyên mẫu.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'tu-loai'), 'choice', 'basic', 'Customer ___ is our top priority.', ARRAY['satisfy', 'satisfied', 'satisfaction', 'satisfying']::text[], 2::int, ARRAY[]::text[], 'Cần danh từ làm chủ ngữ: satisfaction.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'tu-loai'), 'fill', 'basic', 'The hotel staff were very ___ (help) during our stay.', ARRAY[]::text[], NULL::int, ARRAY['helpful']::text[], 'Sau "very" và động từ to be → tính từ helpful.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'tu-loai'), 'fill', 'basic', 'The shipment arrived ___ (late) than expected.', ARRAY[]::text[], NULL::int, ARRAY['later']::text[], 'So sánh với "than" → dạng so sánh hơn của late: later.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'tu-loai'), 'error', 'basic', 'The [[company]] [[successful]] [[launched]] its new [[product]] last month.', ARRAY[]::text[], 1::int, ARRAY[]::text[], 'Bổ nghĩa cho động từ "launched" phải là trạng từ successfully.', 'mistakes', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'tu-loai'), 'choice', 'intermediate', 'The new software allows staff to process orders more ___.', ARRAY['efficient', 'efficiency', 'efficiently', 'efficiencies']::text[], 2::int, ARRAY[]::text[], '"more ___" đứng sau động từ "process orders" → trạng từ efficiently.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'tu-loai'), 'choice', 'intermediate', 'Ms. Tanaka was praised for her ___ to the project.', ARRAY['contribute', 'contributing', 'contributor', 'contribution']::text[], 3::int, ARRAY[]::text[], 'Sau tính từ sở hữu "her" cần danh từ chỉ sự việc: contribution.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'tu-loai'), 'choice', 'intermediate', 'The proposal was rejected because it was not financially ___.', ARRAY['feasibility', 'feasible', 'feasibly', 'feasibleness']::text[], 1::int, ARRAY[]::text[], 'Sau "was not" (to be) cần tính từ; "financially" là trạng từ bổ nghĩa cho tính từ.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'tu-loai'), 'choice', 'intermediate', 'Applicants should ___ their résumés by Friday.', ARRAY['submission', 'submit', 'submissive', 'submitted']::text[], 1::int, ARRAY[]::text[], 'Sau "should" là động từ nguyên mẫu submit.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'tu-loai'), 'fill', 'intermediate', 'The director spoke ___ (confident) about the merger.', ARRAY[]::text[], NULL::int, ARRAY['confidently']::text[], 'Bổ nghĩa cho động từ "spoke" → confidently.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'tu-loai'), 'fill', 'intermediate', 'We appreciate your ___ (patient) while we upgrade our system.', ARRAY[]::text[], NULL::int, ARRAY['patience']::text[], 'Sau "your" cần danh từ: patience.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'tu-loai'), 'error', 'intermediate', 'The [[marketing]] team made a [[decide]] to [[postpone]] the [[campaign]].', ARRAY[]::text[], 1::int, ARRAY[]::text[], 'Sau mạo từ "a" cần danh từ decision.', 'mistakes', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'tu-loai'), 'error', 'intermediate', 'Our [[revised]] schedule is [[consideration]] more [[realistic]] than the [[original]] one.', ARRAY[]::text[], 1::int, ARRAY[]::text[], 'Bổ nghĩa cho tính từ so sánh "more realistic" cần trạng từ considerably.', 'mistakes', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'tu-loai'), 'choice', 'advanced', 'The board members were ___ divided on the issue of relocation.', ARRAY['sharp', 'sharply', 'sharpen', 'sharpness']::text[], 1::int, ARRAY[]::text[], 'Bổ nghĩa cho tính từ/phân từ "divided" → trạng từ sharply.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'tu-loai'), 'choice', 'advanced', 'The consultant offered several ___ suggestions for reducing costs.', ARRAY['practice', 'practically', 'practical', 'practicality']::text[], 2::int, ARRAY[]::text[], 'Trước danh từ "suggestions" cần tính từ practical.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'tu-loai'), 'fill', 'advanced', 'Due to ___ (unpredict) weather, the outdoor event was moved indoors.', ARRAY[]::text[], NULL::int, ARRAY['unpredictable']::text[], 'Trước danh từ "weather" cần tính từ unpredictable.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'tu-loai'), 'error', 'advanced', 'Despite [[its]] [[relative]] small size, the firm has [[consistently]] [[outperformed]] its rivals.', ARRAY[]::text[], 1::int, ARRAY[]::text[], 'Bổ nghĩa cho tính từ "small" cần trạng từ relatively.', 'mistakes', now())
INSERT INTO "grammar_topics" ("slug", "name", "group_name", "level", "sort_order", "summary", "lesson", "toeic_categories", "roadmap_labels", "updated_at") VALUES ('danh-tu-mao-tu', 'Danh từ đếm được / không đếm được, mạo từ', 'Danh từ', 'basic', 20, 'Phân biệt danh từ đếm được và không đếm được, dùng a/an/the và từ chỉ lượng cho đúng.', '{"when_to_use":"Dùng khi chỗ trống đứng sau từ chỉ lượng (many, much, a few, a little, each, every…) hoặc khi phải chọn giữa dạng số ít / số nhiều của danh từ. TOEIC hay hỏi các danh từ không đếm được trong công sở như information, equipment, furniture, advice, luggage.","structure":"Danh từ đếm được có số ít/số nhiều (a report, two reports). Danh từ không đếm được không có \"a/an\", không thêm -s (information, equipment, advice, staff dùng như tập hợp).\nTừ chỉ lượng:\n• many / a few / few / several / a number of + danh từ đếm được số nhiều.\n• much / a little / little / a great deal of / an amount of + danh từ không đếm được.\n• each / every / another + danh từ đếm được số ít.\n• some / any / a lot of / most + cả hai loại.\nMạo từ: a/an với danh từ đếm được số ít chưa xác định (an hour, a university); the với vật đã xác định, duy nhất, đã nhắc tới.","examples":[{"en":"We need more information about the conference.","vi":"Chúng tôi cần thêm thông tin về hội nghị."},{"en":"Each employee receives an annual bonus.","vi":"Mỗi nhân viên nhận thưởng hằng năm."},{"en":"Only a few applicants met the requirements.","vi":"Chỉ vài ứng viên đáp ứng yêu cầu."},{"en":"The equipment in the lab is very expensive.","vi":"Thiết bị trong phòng thí nghiệm rất đắt."}],"mistakes":[{"wrong":"We bought new equipments for the office.","right":"We bought new equipment for the office.","note":"\"equipment\" không đếm được, không thêm -s."},{"wrong":"Every employees must attend.","right":"Every employee must attend.","note":"\"every\" đi với danh từ số ít."},{"wrong":"There is too many traffic today.","right":"There is too much traffic today.","note":"\"traffic\" không đếm được → much."}],"signals":["Từ chỉ lượng ngay trước chỗ trống: each/every → số ít; many/several/a few → số nhiều.","Bốn lựa chọn khác nhau chỉ ở -s / không -s → xét danh từ đếm được hay không và từ chỉ lượng.","Danh từ không đếm được hay gặp: information, equipment, furniture, advice, feedback, luggage, merchandise, access."]}'::jsonb, ARRAY['word_form']::text[], ARRAY['Danh từ đếm được / không đếm được, mạo từ a/an/the']::text[], now()) ON CONFLICT ("slug") DO NOTHING;
INSERT INTO "grammar_formulas" ("topic_id", "sort_order", "pattern", "usage", "examples", "updated_at") SELECT * FROM (VALUES
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'danh-tu-mao-tu'), 0, 'many / a few / several / a number of + N(số nhiều)', 'Danh từ đếm được số nhiều.', '[{"en":"several candidates","vi":"vài ứng viên"}]'::jsonb, now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'danh-tu-mao-tu'), 1, 'much / a little / an amount of / a great deal of + N(không đếm được)', 'Danh từ không đếm được.', '[{"en":"a great deal of effort","vi":"rất nhiều công sức"}]'::jsonb, now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'danh-tu-mao-tu'), 2, 'each / every / another + N(số ít) + V(số ít)', 'Each/every đi với danh từ và động từ số ít.', '[{"en":"Every room has a view.","vi":"Phòng nào cũng có tầm nhìn."}]'::jsonb, now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'danh-tu-mao-tu'), 3, 'a + phụ âm (âm)  |  an + nguyên âm (âm)', 'Chọn a/an theo âm đầu: an hour, a university.', '[{"en":"an honest answer, a useful tip","vi":""}]'::jsonb, now())
INSERT INTO "grammar_exercises" ("topic_id", "kind", "level", "prompt", "options", "answer_index", "accepted_answers", "explanation", "lesson_section", "updated_at") SELECT * FROM (VALUES
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'danh-tu-mao-tu'), 'choice', 'basic', 'Could you give me some ___ about the new procedure?', ARRAY['informations', 'information', 'an information', 'informative']::text[], 1::int, ARRAY[]::text[], '"information" không đếm được, không thêm -s, không dùng "an".', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'danh-tu-mao-tu'), 'choice', 'basic', '___ employee must wear an ID badge.', ARRAY['All', 'Every', 'Many', 'Several']::text[], 1::int, ARRAY[]::text[], 'Danh từ số ít "employee" → Every.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'danh-tu-mao-tu'), 'choice', 'basic', 'We received ___ complaints about the noise.', ARRAY['much', 'a little', 'a few', 'an amount of']::text[], 2::int, ARRAY[]::text[], '"complaints" đếm được số nhiều → a few.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'danh-tu-mao-tu'), 'choice', 'basic', 'She is ___ honest and reliable worker.', ARRAY['a', 'an', 'the', '(không cần mạo từ)']::text[], 1::int, ARRAY[]::text[], '"honest" bắt đầu bằng âm nguyên âm /ɒ/ → an.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'danh-tu-mao-tu'), 'choice', 'basic', 'The office needs new ___.', ARRAY['furniture', 'furnitures', 'a furniture', 'furnishing']::text[], 0::int, ARRAY[]::text[], '"furniture" không đếm được.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'danh-tu-mao-tu'), 'fill', 'basic', 'There are several ___ (candidate) for the position.', ARRAY[]::text[], NULL::int, ARRAY['candidates']::text[], '"several" + danh từ số nhiều.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'danh-tu-mao-tu'), 'fill', 'basic', 'How ___ (much/many) luggage are you bringing?', ARRAY[]::text[], NULL::int, ARRAY['much']::text[], '"luggage" không đếm được → much.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'danh-tu-mao-tu'), 'error', 'basic', 'Each [[participants]] [[will]] [[receive]] a [[certificate]].', ARRAY[]::text[], 0::int, ARRAY[]::text[], '"Each" + danh từ số ít: participant.', 'mistakes', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'danh-tu-mao-tu'), 'choice', 'intermediate', 'The training session provided a great deal of useful ___.', ARRAY['advices', 'advice', 'advisor', 'advise']::text[], 1::int, ARRAY[]::text[], '"a great deal of" + danh từ không đếm được: advice.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'danh-tu-mao-tu'), 'choice', 'intermediate', 'A ___ of customers have asked for a refund.', ARRAY['amount', 'deal', 'number', 'little']::text[], 2::int, ARRAY[]::text[], '"a number of" + danh từ đếm được số nhiều; động từ chia số nhiều "have".', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'danh-tu-mao-tu'), 'choice', 'intermediate', 'Only ___ progress has been made on the renovation.', ARRAY['few', 'little', 'many', 'several']::text[], 1::int, ARRAY[]::text[], '"progress" không đếm được → little.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'danh-tu-mao-tu'), 'choice', 'intermediate', 'Mr. Silva is ___ only person who has the key.', ARRAY['a', 'an', 'the', 'one']::text[], 2::int, ARRAY[]::text[], 'Người duy nhất, xác định → the.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'danh-tu-mao-tu'), 'fill', 'intermediate', 'The store sells a wide range of ___ (merchandise).', ARRAY[]::text[], NULL::int, ARRAY['merchandise']::text[], '"merchandise" không đếm được, giữ nguyên.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'danh-tu-mao-tu'), 'fill', 'intermediate', 'Please send me ___ copy of the contract. (a/an)', ARRAY[]::text[], NULL::int, ARRAY['a']::text[], '"copy" bắt đầu bằng phụ âm → a.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'danh-tu-mao-tu'), 'error', 'intermediate', 'The [[staff]] lounge has [[many]] [[equipment]] for [[relaxation]].', ARRAY[]::text[], 1::int, ARRAY[]::text[], '"equipment" không đếm được → much / a lot of.', 'mistakes', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'danh-tu-mao-tu'), 'error', 'intermediate', 'We have [[an]] [[university]] [[graduate]] on [[our]] team.', ARRAY[]::text[], 0::int, ARRAY[]::text[], '"university" đọc /juː/ (phụ âm) → a.', 'mistakes', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'danh-tu-mao-tu'), 'choice', 'advanced', 'The amount of ___ generated by the factory has decreased.', ARRAY['wastes', 'waste', 'a waste', 'wasting']::text[], 1::int, ARRAY[]::text[], '"the amount of" + danh từ không đếm được.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'danh-tu-mao-tu'), 'choice', 'advanced', 'Neither of the two ___ was suitable for the event.', ARRAY['venue', 'venues', 'a venue', 'the venue']::text[], 1::int, ARRAY[]::text[], '"neither of the two" + danh từ số nhiều; động từ chia số ít.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'danh-tu-mao-tu'), 'fill', 'advanced', 'Several pieces of ___ (evidence) were presented to the committee.', ARRAY[]::text[], NULL::int, ARRAY['evidence']::text[], '"evidence" không đếm được; đếm bằng "pieces of".', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'danh-tu-mao-tu'), 'error', 'advanced', 'The [[number]] of [[visitor]] to the museum [[has]] doubled [[since]] June.', ARRAY[]::text[], 1::int, ARRAY[]::text[], '"the number of" + danh từ số nhiều: visitors.', 'mistakes', now())
INSERT INTO "grammar_topics" ("slug", "name", "group_name", "level", "sort_order", "summary", "lesson", "toeic_categories", "roadmap_labels", "updated_at") VALUES ('dai-tu', 'Đại từ nhân xưng, sở hữu, phản thân', 'Đại từ', 'basic', 30, 'Chọn đúng đại từ chủ ngữ, tân ngữ, tính từ sở hữu, đại từ sở hữu và đại từ phản thân.', '{"when_to_use":"Câu Đại từ trong Part 5 cho 4 dạng của cùng một ngôi (he, him, his, himself). Hãy xem chỗ trống đứng ở vị trí chủ ngữ, tân ngữ, trước danh từ hay đứng một mình thay cho cụm danh từ.","structure":"• Chủ ngữ: I, you, he, she, it, we, they — đứng trước động từ.\n• Tân ngữ: me, you, him, her, it, us, them — sau động từ hoặc giới từ.\n• Tính từ sở hữu: my, your, his, her, its, our, their — đứng TRƯỚC danh từ.\n• Đại từ sở hữu: mine, yours, his, hers, ours, theirs — đứng một mình, thay cho \"tính từ sở hữu + danh từ\".\n• Phản thân: myself, himself, themselves… — khi chủ ngữ và tân ngữ là một người, hoặc để nhấn mạnh; \"by + oneself\" = một mình.","examples":[{"en":"She sent the report to him yesterday.","vi":"Cô ấy gửi báo cáo cho anh ấy hôm qua."},{"en":"Our office is larger than theirs.","vi":"Văn phòng chúng tôi lớn hơn văn phòng của họ."},{"en":"The manager prepared the slides herself.","vi":"Quản lý tự chuẩn bị slide."},{"en":"The company updated its website.","vi":"Công ty cập nhật trang web của mình."}],"mistakes":[{"wrong":"Please contact Mr. Lee or myself.","right":"Please contact Mr. Lee or me.","note":"Tân ngữ thường, không dùng phản thân."},{"wrong":"The firm announced it new policy.","right":"The firm announced its new policy.","note":"Trước danh từ là tính từ sở hữu \"its\"."},{"wrong":"This seat is her.","right":"This seat is hers.","note":"Đứng một mình thay \"her seat\" → hers."}],"signals":["Chỗ trống trước danh từ → tính từ sở hữu (his, their, its).","Chỗ trống sau động từ/giới từ, câu đã có chủ ngữ khác → tân ngữ (him, them).","Chủ ngữ và tân ngữ cùng người, hoặc có \"by ___\" → phản thân.","Chỗ trống đứng cuối, so sánh với vật đã nhắc (\"than ___\") → đại từ sở hữu."]}'::jsonb, ARRAY['pronoun']::text[], ARRAY['Đại từ nhân xưng, tính từ và đại từ sở hữu']::text[], now()) ON CONFLICT ("slug") DO NOTHING;
INSERT INTO "grammar_formulas" ("topic_id", "sort_order", "pattern", "usage", "examples", "updated_at") SELECT * FROM (VALUES
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'dai-tu'), 0, 'my/your/his/her/its/our/their + N', 'Tính từ sở hữu luôn đi kèm danh từ.', '[{"en":"their latest model","vi":"mẫu mới nhất của họ"}]'::jsonb, now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'dai-tu'), 1, 'mine/yours/his/hers/ours/theirs (đứng một mình)', 'Đại từ sở hữu = tính từ sở hữu + danh từ.', '[{"en":"Your idea is better than mine.","vi":"Ý tưởng của bạn hay hơn của tôi."}]'::jsonb, now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'dai-tu'), 2, 'S + V + oneself  |  by + oneself', 'Phản thân khi chủ ngữ = tân ngữ; "by oneself" = một mình.', '[{"en":"He finished the project by himself.","vi":"Anh ấy tự làm xong dự án."}]'::jsonb, now())
INSERT INTO "grammar_exercises" ("topic_id", "kind", "level", "prompt", "options", "answer_index", "accepted_answers", "explanation", "lesson_section", "updated_at") SELECT * FROM (VALUES
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'dai-tu'), 'choice', 'basic', 'Ms. Park asked ___ assistant to book a flight.', ARRAY['she', 'her', 'hers', 'herself']::text[], 1::int, ARRAY[]::text[], 'Trước danh từ "assistant" → tính từ sở hữu her.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'dai-tu'), 'choice', 'basic', 'The clients thanked ___ for the quick response.', ARRAY['we', 'our', 'us', 'ours']::text[], 2::int, ARRAY[]::text[], 'Sau động từ "thanked" → tân ngữ us.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'dai-tu'), 'choice', 'basic', 'If you need help, please let ___ know.', ARRAY['I', 'me', 'my', 'mine']::text[], 1::int, ARRAY[]::text[], 'Sau "let" → tân ngữ me.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'dai-tu'), 'choice', 'basic', 'The company celebrated ___ tenth anniversary.', ARRAY['it', 'it''s', 'its', 'itself']::text[], 2::int, ARRAY[]::text[], 'Trước danh từ → its (không phải it''s = it is).', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'dai-tu'), 'choice', 'basic', 'This umbrella isn''t mine. Is it ___?', ARRAY['your', 'you', 'yours', 'yourself']::text[], 2::int, ARRAY[]::text[], 'Đứng một mình thay "your umbrella" → yours.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'dai-tu'), 'fill', 'basic', 'Mr. Kim installed the software by ___ (he).', ARRAY[]::text[], NULL::int, ARRAY['himself']::text[], '"by + phản thân" = tự mình.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'dai-tu'), 'fill', 'basic', '___ (they) proposal was accepted by the board.', ARRAY[]::text[], NULL::int, ARRAY['Their', 'their']::text[], 'Trước danh từ "proposal" → Their.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'dai-tu'), 'error', 'basic', '[[Him]] and [[his]] colleagues [[attended]] the [[workshop]].', ARRAY[]::text[], 0::int, ARRAY[]::text[], 'Vị trí chủ ngữ → He.', 'mistakes', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'dai-tu'), 'choice', 'intermediate', 'Employees who wish to attend should register ___ online.', ARRAY['them', 'themselves', 'their', 'theirs']::text[], 1::int, ARRAY[]::text[], 'Chủ ngữ "employees" và tân ngữ là cùng người → themselves.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'dai-tu'), 'choice', 'intermediate', 'Our sales figures were higher than ___ last quarter.', ARRAY['they', 'them', 'their', 'theirs']::text[], 3::int, ARRAY[]::text[], 'Thay "their sales figures" → theirs.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'dai-tu'), 'choice', 'intermediate', 'The CEO ___ will present the award.', ARRAY['she', 'her', 'herself', 'hers']::text[], 2::int, ARRAY[]::text[], 'Nhấn mạnh chủ ngữ → herself.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'dai-tu'), 'choice', 'intermediate', 'Please forward the e-mail to Ms. Ruiz and ___.', ARRAY['I', 'me', 'myself', 'mine']::text[], 1::int, ARRAY[]::text[], 'Sau giới từ "to" → tân ngữ me.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'dai-tu'), 'fill', 'intermediate', 'The design team presented ___ (they) ideas to the client.', ARRAY[]::text[], NULL::int, ARRAY['their']::text[], 'Trước danh từ "ideas" → their.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'dai-tu'), 'fill', 'intermediate', 'Ms. Ito prefers to edit the reports ___ (she).', ARRAY[]::text[], NULL::int, ARRAY['herself']::text[], 'Nhấn mạnh tự làm → herself.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'dai-tu'), 'error', 'intermediate', 'The [[board]] approved the plan, but [[their]] did not [[approve]] the [[budget]].', ARRAY[]::text[], 1::int, ARRAY[]::text[], 'Vị trí chủ ngữ của mệnh đề → they.', 'mistakes', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'dai-tu'), 'error', 'intermediate', 'Every [[manager]] should review [[their]] team''s goals [[theirself]] [[before]] Friday.', ARRAY[]::text[], 2::int, ARRAY[]::text[], 'Không có "theirself"; dùng themselves (hoặc himself/herself).', 'mistakes', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'dai-tu'), 'choice', 'advanced', 'Although the idea was originally ___, Mr. Cho received the credit.', ARRAY['me', 'my', 'mine', 'myself']::text[], 2::int, ARRAY[]::text[], 'Đứng một mình sau "was" thay cho "my idea" → mine.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'dai-tu'), 'choice', 'advanced', 'The guests helped ___ to refreshments in the lobby.', ARRAY['them', 'their', 'themselves', 'theirs']::text[], 2::int, ARRAY[]::text[], '"help oneself to" = tự lấy dùng.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'dai-tu'), 'fill', 'advanced', 'Neither the manager nor ___ (I) was informed of the change.', ARRAY[]::text[], NULL::int, ARRAY['I']::text[], 'Vị trí chủ ngữ (neither … nor …) → I.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'dai-tu'), 'error', 'advanced', 'The [[committee]] will announce [[it''s]] [[decision]] once [[all]] votes are counted.', ARRAY[]::text[], 1::int, ARRAY[]::text[], 'Tính từ sở hữu là its, không phải it''s (= it is).', 'mistakes', now())
INSERT INTO "grammar_topics" ("slug", "name", "group_name", "level", "sort_order", "summary", "lesson", "toeic_categories", "roadmap_labels", "updated_at") VALUES ('cac-thi-co-ban', 'Các thì cơ bản', 'Động từ & thì', 'basic', 40, 'Hiện tại đơn, hiện tại tiếp diễn, quá khứ đơn, tương lai đơn và dấu hiệu nhận biết.', '{"when_to_use":"Khi 4 lựa chọn là cùng một động từ ở nhiều thì khác nhau. Hãy tìm trạng từ chỉ thời gian trong câu (yesterday, next week, every day, currently…) — đó là chìa khóa.","structure":"• Hiện tại đơn: S + V(s/es) — thói quen, sự thật, lịch trình. Dấu hiệu: every, usually, always, often.\n• Hiện tại tiếp diễn: S + am/is/are + V-ing — đang diễn ra, kế hoạch gần. Dấu hiệu: now, currently, at the moment, this week.\n• Quá khứ đơn: S + V2/V-ed — việc đã xong trong quá khứ. Dấu hiệu: yesterday, last…, … ago, in 2020.\n• Tương lai đơn: S + will + V — dự đoán, quyết định, hứa hẹn. Dấu hiệu: tomorrow, next…, soon. \"be going to + V\" cho kế hoạch đã định.\nMệnh đề thời gian (when, before, after, as soon as, until) nói về tương lai dùng HIỆN TẠI ĐƠN, không dùng will.","examples":[{"en":"The store opens at 9 a.m. every day.","vi":"Cửa hàng mở lúc 9 giờ mỗi ngày."},{"en":"We are currently reviewing all applications.","vi":"Chúng tôi đang xem xét mọi hồ sơ."},{"en":"The shipment arrived two days ago.","vi":"Lô hàng đến cách đây hai ngày."},{"en":"I will call you as soon as the report is ready.","vi":"Tôi sẽ gọi ngay khi báo cáo xong. (mệnh đề thời gian dùng hiện tại)"}],"mistakes":[{"wrong":"We will contact you when we will receive the payment.","right":"We will contact you when we receive the payment.","note":"Mệnh đề thời gian tương lai dùng hiện tại đơn."},{"wrong":"She attend the meeting yesterday.","right":"She attended the meeting yesterday.","note":"\"yesterday\" → quá khứ đơn."},{"wrong":"The train is leaving every hour.","right":"The train leaves every hour.","note":"Lịch trình lặp lại → hiện tại đơn."}],"signals":["yesterday / last / ago / in + năm đã qua → quá khứ đơn.","next / tomorrow / soon / by + mốc tương lai (không có \"by the time\") → will.","currently / now / at the moment → hiện tại tiếp diễn.","Sau when / before / after / as soon as / once (nói về tương lai) → hiện tại đơn."]}'::jsonb, ARRAY['verb_tense']::text[], ARRAY['Các thì cơ bản: hiện tại đơn, hiện tại tiếp diễn, quá khứ đơn, tương lai đơn']::text[], now()) ON CONFLICT ("slug") DO NOTHING;
INSERT INTO "grammar_formulas" ("topic_id", "sort_order", "pattern", "usage", "examples", "updated_at") SELECT * FROM (VALUES
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cac-thi-co-ban'), 0, 'S + V(s/es)', 'Hiện tại đơn: thói quen, sự thật, lịch trình.', '[{"en":"The bus leaves at 7:30.","vi":"Xe buýt chạy lúc 7:30."}]'::jsonb, now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cac-thi-co-ban'), 1, 'S + am/is/are + V-ing', 'Hiện tại tiếp diễn: đang diễn ra quanh thời điểm nói.', '[{"en":"They are renovating the lobby.","vi":"Họ đang sửa sảnh."}]'::jsonb, now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cac-thi-co-ban'), 2, 'S + V2/V-ed', 'Quá khứ đơn: việc đã kết thúc.', '[{"en":"The CEO resigned last year.","vi":"CEO từ chức năm ngoái."}]'::jsonb, now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cac-thi-co-ban'), 3, 'S + will + V  |  when/after/before + S + V(hiện tại)', 'Tương lai đơn; mệnh đề thời gian dùng hiện tại.', '[{"en":"We will start after everyone arrives.","vi":"Sẽ bắt đầu khi mọi người đến."}]'::jsonb, now())
INSERT INTO "grammar_exercises" ("topic_id", "kind", "level", "prompt", "options", "answer_index", "accepted_answers", "explanation", "lesson_section", "updated_at") SELECT * FROM (VALUES
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cac-thi-co-ban'), 'choice', 'basic', 'The company ___ a new branch in Hanoi last year.', ARRAY['opens', 'opened', 'will open', 'is opening']::text[], 1::int, ARRAY[]::text[], '"last year" → quá khứ đơn.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cac-thi-co-ban'), 'choice', 'basic', 'Our team ___ every Monday morning.', ARRAY['meets', 'met', 'is meeting', 'meeting']::text[], 0::int, ARRAY[]::text[], '"every Monday" → hiện tại đơn, chủ ngữ số ít.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cac-thi-co-ban'), 'choice', 'basic', 'The technicians ___ the air conditioners at the moment.', ARRAY['repair', 'repaired', 'are repairing', 'will repair']::text[], 2::int, ARRAY[]::text[], '"at the moment" → hiện tại tiếp diễn.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cac-thi-co-ban'), 'choice', 'basic', 'The new manager ___ next Monday.', ARRAY['start', 'started', 'starts', 'will start']::text[], 3::int, ARRAY[]::text[], '"next Monday" → tương lai (will start).', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cac-thi-co-ban'), 'choice', 'basic', 'Please wait here until Mr. Brown ___.', ARRAY['arrives', 'will arrive', 'arrived', 'arriving']::text[], 0::int, ARRAY[]::text[], 'Sau "until" nói về tương lai dùng hiện tại đơn.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cac-thi-co-ban'), 'fill', 'basic', 'The conference ___ (take) place in Singapore two years ago.', ARRAY[]::text[], NULL::int, ARRAY['took']::text[], '"two years ago" → quá khứ đơn của take: took.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cac-thi-co-ban'), 'fill', 'basic', 'Ms. Lee usually ___ (work) from home on Fridays.', ARRAY[]::text[], NULL::int, ARRAY['works']::text[], '"usually" → hiện tại đơn, ngôi 3 số ít.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cac-thi-co-ban'), 'error', 'basic', 'The [[shipment]] [[arrive]] at the warehouse [[yesterday]] [[afternoon]].', ARRAY[]::text[], 1::int, ARRAY[]::text[], '"yesterday" → arrived.', 'mistakes', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cac-thi-co-ban'), 'choice', 'intermediate', 'We will send the invoice as soon as the order ___.', ARRAY['will ship', 'ships', 'shipped', 'is shipped']::text[], 3::int, ARRAY[]::text[], 'Mệnh đề thời gian dùng hiện tại; đơn hàng "được" gửi → is shipped.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cac-thi-co-ban'), 'choice', 'intermediate', 'Mr. Garcia ___ for the company since he graduated.', ARRAY['works', 'worked', 'has worked', 'will work']::text[], 2::int, ARRAY[]::text[], '"since" → hiện tại hoàn thành (xem chủ điểm Thì hoàn thành).', 'signals', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cac-thi-co-ban'), 'choice', 'intermediate', 'Currently, the marketing department ___ a new campaign.', ARRAY['develops', 'developed', 'is developing', 'will develop']::text[], 2::int, ARRAY[]::text[], '"Currently" → hiện tại tiếp diễn.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cac-thi-co-ban'), 'choice', 'intermediate', 'The museum ___ closed to the public until further notice.', ARRAY['remains', 'remained', 'remaining', 'to remain']::text[], 0::int, ARRAY[]::text[], 'Tình trạng hiện tại → hiện tại đơn remains.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cac-thi-co-ban'), 'fill', 'intermediate', 'I ___ (call) you once I get the results.', ARRAY[]::text[], NULL::int, ARRAY['will call', '''ll call']::text[], 'Mệnh đề chính nói về tương lai → will call.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cac-thi-co-ban'), 'fill', 'intermediate', 'The flight to Tokyo ___ (depart) at 6:15 tomorrow, according to the schedule.', ARRAY[]::text[], NULL::int, ARRAY['departs']::text[], 'Lịch trình cố định → hiện tại đơn dù nói về tương lai.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cac-thi-co-ban'), 'error', 'intermediate', 'The [[manager]] will review the report after she [[will return]] [[from]] her [[trip]].', ARRAY[]::text[], 1::int, ARRAY[]::text[], 'Sau "after" dùng hiện tại: returns.', 'mistakes', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cac-thi-co-ban'), 'error', 'intermediate', 'Last week, the [[firm]] [[hires]] three [[new]] [[engineers]].', ARRAY[]::text[], 1::int, ARRAY[]::text[], '"Last week" → hired.', 'mistakes', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cac-thi-co-ban'), 'choice', 'advanced', 'By the time the guests arrived, the caterers ___ the tables.', ARRAY['set', 'had set', 'have set', 'are setting']::text[], 1::int, ARRAY[]::text[], 'Việc xảy ra trước một mốc quá khứ → quá khứ hoàn thành (nâng cao).', 'signals', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cac-thi-co-ban'), 'choice', 'advanced', 'The CEO ___ the shareholders at next month''s annual meeting.', ARRAY['addressed', 'is addressing', 'addresses', 'has addressed']::text[], 1::int, ARRAY[]::text[], 'Kế hoạch đã sắp xếp trong tương lai gần → hiện tại tiếp diễn.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cac-thi-co-ban'), 'fill', 'advanced', 'Unless sales ___ (improve) soon, the store will close.', ARRAY[]::text[], NULL::int, ARRAY['improve']::text[], 'Sau "unless" (điều kiện tương lai) dùng hiện tại đơn.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cac-thi-co-ban'), 'error', 'advanced', 'The [[board]] [[is deciding]] on the budget [[before]] the fiscal year [[ended]].', ARRAY[]::text[], 3::int, ARRAY[]::text[], 'Mốc tương lai → ends (hiện tại đơn sau before).', 'mistakes', now())
INSERT INTO "grammar_topics" ("slug", "name", "group_name", "level", "sort_order", "summary", "lesson", "toeic_categories", "roadmap_labels", "updated_at") VALUES ('thi-hoan-thanh', 'Thì hoàn thành', 'Động từ & thì', 'intermediate', 50, 'Hiện tại hoàn thành, quá khứ hoàn thành, tương lai hoàn thành và các dấu hiệu since/for/by the time.', '{"when_to_use":"Dùng khi hành động nối hai mốc thời gian: từ quá khứ kéo tới hiện tại (hiện tại hoàn thành), xảy ra trước một mốc quá khứ (quá khứ hoàn thành), hoặc sẽ xong trước một mốc tương lai (tương lai hoàn thành).","structure":"• Hiện tại hoàn thành: S + have/has + V3. Dấu hiệu: since, for, already, yet, recently, so far, over the past…\n• Quá khứ hoàn thành: S + had + V3. Dấu hiệu: by the time + quá khứ, before/after + quá khứ.\n• Tương lai hoàn thành: S + will have + V3. Dấu hiệu: by + mốc tương lai, by the time + hiện tại.\n• Since + mốc thời gian (since 2019); for + khoảng thời gian (for three years).","examples":[{"en":"The company has expanded rapidly over the past five years.","vi":"Công ty mở rộng nhanh trong 5 năm qua."},{"en":"By the time we arrived, the meeting had already started.","vi":"Khi chúng tôi đến, cuộc họp đã bắt đầu."},{"en":"By next March, we will have completed the renovation.","vi":"Đến tháng Ba tới, chúng tôi sẽ sửa xong."},{"en":"Ms. Patel has worked here since 2018.","vi":"Bà Patel làm ở đây từ 2018."}],"mistakes":[{"wrong":"I have met him yesterday.","right":"I met him yesterday.","note":"Có mốc quá khứ cụ thể → quá khứ đơn, không dùng hoàn thành."},{"wrong":"She works here since 2020.","right":"She has worked here since 2020.","note":"\"since\" → hiện tại hoàn thành."},{"wrong":"By the end of this year, we will complete 50 projects.","right":"By the end of this year, we will have completed 50 projects.","note":"\"by + mốc tương lai\" → tương lai hoàn thành."}],"signals":["since / for / over the past / so far / recently → have/has + V3.","by the time + quá khứ đơn → had + V3.","by + mốc tương lai (by next week, by 2030) → will have + V3.","already / yet / just → thường dùng hoàn thành."]}'::jsonb, ARRAY['verb_tense']::text[], ARRAY['Thì hoàn thành và sự hòa hợp chủ ngữ – động từ']::text[], now()) ON CONFLICT ("slug") DO NOTHING;
INSERT INTO "grammar_formulas" ("topic_id", "sort_order", "pattern", "usage", "examples", "updated_at") SELECT * FROM (VALUES
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'thi-hoan-thanh'), 0, 'S + have/has + V3 (+ since/for)', 'Hiện tại hoàn thành: từ quá khứ đến hiện tại, kết quả còn liên quan.', '[{"en":"Sales have increased by 20% this year.","vi":"Doanh số tăng 20% năm nay."}]'::jsonb, now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'thi-hoan-thanh'), 1, 'By the time + S + V2, S + had + V3', 'Quá khứ hoàn thành: xảy ra trước một mốc quá khứ.', '[{"en":"By the time I called, she had left.","vi":"Khi tôi gọi, cô ấy đã đi."}]'::jsonb, now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'thi-hoan-thanh'), 2, 'By + mốc tương lai, S + will have + V3', 'Tương lai hoàn thành: sẽ xong trước mốc tương lai.', '[{"en":"By Friday, we will have shipped all orders.","vi":"Đến thứ Sáu sẽ gửi xong mọi đơn."}]'::jsonb, now())
INSERT INTO "grammar_exercises" ("topic_id", "kind", "level", "prompt", "options", "answer_index", "accepted_answers", "explanation", "lesson_section", "updated_at") SELECT * FROM (VALUES
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'thi-hoan-thanh'), 'choice', 'basic', 'Mr. Wong ___ in the accounting department for ten years.', ARRAY['works', 'worked', 'has worked', 'will work']::text[], 2::int, ARRAY[]::text[], '"for ten years" (đến nay) → has worked.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'thi-hoan-thanh'), 'choice', 'basic', 'We ___ the report yet.', ARRAY['haven''t finished', 'didn''t finish', 'don''t finish', 'won''t finish']::text[], 0::int, ARRAY[]::text[], '"yet" ở câu phủ định → hiện tại hoàn thành.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'thi-hoan-thanh'), 'choice', 'basic', 'The price of fuel ___ since January.', ARRAY['rises', 'rose', 'has risen', 'is rising']::text[], 2::int, ARRAY[]::text[], '"since January" → has risen.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'thi-hoan-thanh'), 'choice', 'basic', 'Ms. Ahmed ___ already ___ the contract.', ARRAY['has / signed', 'is / signing', 'did / sign', 'was / signed']::text[], 0::int, ARRAY[]::text[], '"already" → has signed.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'thi-hoan-thanh'), 'fill', 'basic', 'They ___ (live) in this city since 2015.', ARRAY[]::text[], NULL::int, ARRAY['have lived', '''ve lived']::text[], '"since 2015" → have lived.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'thi-hoan-thanh'), 'fill', 'basic', 'I ___ (not / see) the new office yet.', ARRAY[]::text[], NULL::int, ARRAY['haven''t seen', 'have not seen']::text[], '"yet" → hiện tại hoàn thành phủ định.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'thi-hoan-thanh'), 'error', 'basic', 'The [[company]] [[has opened]] a new store [[last]] [[month]].', ARRAY[]::text[], 1::int, ARRAY[]::text[], '"last month" là mốc quá khứ → opened.', 'mistakes', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'thi-hoan-thanh'), 'choice', 'intermediate', 'By the time the CEO arrived, the presentation ___.', ARRAY['ends', 'has ended', 'had ended', 'will end']::text[], 2::int, ARRAY[]::text[], '"By the time + quá khứ" → had ended.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'thi-hoan-thanh'), 'choice', 'intermediate', 'By the end of next year, the firm ___ 100 new employees.', ARRAY['hires', 'hired', 'will have hired', 'has hired']::text[], 2::int, ARRAY[]::text[], '"By + mốc tương lai" → will have hired.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'thi-hoan-thanh'), 'choice', 'intermediate', 'Over the past decade, online sales ___ steadily.', ARRAY['grow', 'grew', 'have grown', 'had grown']::text[], 2::int, ARRAY[]::text[], '"Over the past decade" → have grown.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'thi-hoan-thanh'), 'choice', 'intermediate', 'The client had already left before Mr. Diaz ___.', ARRAY['arrives', 'arrived', 'has arrived', 'had arrived']::text[], 1::int, ARRAY[]::text[], 'Việc sau trong quá khứ → quá khứ đơn arrived.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'thi-hoan-thanh'), 'fill', 'intermediate', 'By 2030, the city ___ (build) three new subway lines.', ARRAY[]::text[], NULL::int, ARRAY['will have built']::text[], '"By 2030" → will have built.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'thi-hoan-thanh'), 'fill', 'intermediate', 'She told us that she ___ (work) in Paris before moving to London.', ARRAY[]::text[], NULL::int, ARRAY['had worked']::text[], 'Trước một hành động quá khứ → had worked.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'thi-hoan-thanh'), 'error', 'intermediate', 'Since the merger, the [[company]] [[increased]] its [[market]] share [[significantly]].', ARRAY[]::text[], 1::int, ARRAY[]::text[], '"Since" → has increased.', 'mistakes', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'thi-hoan-thanh'), 'error', 'intermediate', 'By the time the [[technician]] [[arrived]], we [[have fixed]] the [[problem]].', ARRAY[]::text[], 2::int, ARRAY[]::text[], 'Trước mốc quá khứ → had fixed.', 'mistakes', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'thi-hoan-thanh'), 'choice', 'advanced', 'Ms. Kato ___ the position for only six months when she was promoted.', ARRAY['has held', 'had held', 'holds', 'will have held']::text[], 1::int, ARRAY[]::text[], 'Khoảng thời gian trước một mốc quá khứ → had held.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'thi-hoan-thanh'), 'choice', 'advanced', 'This is the first time the committee ___ a unanimous decision.', ARRAY['reaches', 'reached', 'has reached', 'had reached']::text[], 2::int, ARRAY[]::text[], '"This is the first time + hiện tại hoàn thành".', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'thi-hoan-thanh'), 'choice', 'advanced', 'When the auditors finish next week, they ___ every account.', ARRAY['will review', 'will have reviewed', 'have reviewed', 'reviewed']::text[], 1::int, ARRAY[]::text[], 'Hoàn tất trước mốc tương lai → will have reviewed.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'thi-hoan-thanh'), 'fill', 'advanced', 'Not until all the forms ___ (submit) will the claim be processed.', ARRAY[]::text[], NULL::int, ARRAY['have been submitted', 'are submitted']::text[], 'Mệnh đề thời gian tương lai, nghĩa bị động → have been submitted / are submitted.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'thi-hoan-thanh'), 'error', 'advanced', 'The [[supplier]] [[has delivered]] [[the]] goods by the time the store [[opened]] yesterday.', ARRAY[]::text[], 1::int, ARRAY[]::text[], 'Trước mốc quá khứ "opened yesterday" → had delivered.', 'mistakes', now())
INSERT INTO "grammar_topics" ("slug", "name", "group_name", "level", "sort_order", "summary", "lesson", "toeic_categories", "roadmap_labels", "updated_at") VALUES ('hoa-hop-chu-ngu-dong-tu', 'Hòa hợp chủ ngữ – động từ', 'Động từ & thì', 'intermediate', 60, 'Chia động từ theo chủ ngữ thật: cụm danh từ dài, each/every, the number of, either/neither, danh từ tập hợp.', '{"when_to_use":"Khi các lựa chọn khác nhau ở dạng số ít/số nhiều của động từ (is/are, has/have, offers/offer). Phải tìm đúng danh từ chính làm chủ ngữ, bỏ qua cụm giới từ và mệnh đề chen giữa.","structure":"• Chủ ngữ là cụm \"N1 + of/with/in + N2\" → chia theo N1 (The list of items IS…).\n• Each / every / everyone / anyone / nobody → số ít.\n• The number of + N(số nhiều) → số ít; A number of + N(số nhiều) → số nhiều.\n• Either/Neither A or/nor B → chia theo B (danh từ gần động từ).\n• A and B → số nhiều; A as well as / along with / together with B → chia theo A.\n• Danh từ không đếm được, V-ing / To V làm chủ ngữ → số ít.","examples":[{"en":"The list of participants is on the desk.","vi":"Danh sách người tham gia ở trên bàn."},{"en":"Each of the rooms has a balcony.","vi":"Mỗi phòng đều có ban công."},{"en":"A number of employees have volunteered.","vi":"Một số nhân viên đã tình nguyện."},{"en":"Neither the manager nor the assistants were available.","vi":"Cả quản lý lẫn trợ lý đều bận."}],"mistakes":[{"wrong":"The quality of the products are excellent.","right":"The quality of the products is excellent.","note":"Chủ ngữ thật là \"quality\" (số ít)."},{"wrong":"Every customer receive a gift.","right":"Every customer receives a gift.","note":"\"Every\" → số ít."},{"wrong":"The number of complaints have dropped.","right":"The number of complaints has dropped.","note":"\"The number of\" → số ít."}],"signals":["Lựa chọn chỉ khác -s / is–are / has–have → tìm danh từ chính, gạch bỏ cụm \"of …\".","Gặp \"each of / one of / the number of\" → số ít.","Gặp \"a number of / both … and / A and B\" → số nhiều."]}'::jsonb, ARRAY['verb_tense']::text[], ARRAY['Thì hoàn thành và sự hòa hợp chủ ngữ – động từ']::text[], now()) ON CONFLICT ("slug") DO NOTHING;
INSERT INTO "grammar_formulas" ("topic_id", "sort_order", "pattern", "usage", "examples", "updated_at") SELECT * FROM (VALUES
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'hoa-hop-chu-ngu-dong-tu'), 0, 'N1 + (of / in / with + N2) + V(theo N1)', 'Chia động từ theo danh từ chính đứng đầu.', '[{"en":"The cost of repairs is high.","vi":"Chi phí sửa chữa cao."}]'::jsonb, now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'hoa-hop-chu-ngu-dong-tu'), 1, 'The number of + Ns + V(số ít)  |  A number of + Ns + V(số nhiều)', 'Phân biệt "the number of" và "a number of".', '[{"en":"The number of visitors has risen.","vi":"Số khách đã tăng."}]'::jsonb, now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'hoa-hop-chu-ngu-dong-tu'), 2, 'Either/Neither A or/nor B + V(theo B)', 'Động từ chia theo danh từ gần nhất.', '[{"en":"Either the staff or the manager is responsible.","vi":""}]'::jsonb, now())
INSERT INTO "grammar_exercises" ("topic_id", "kind", "level", "prompt", "options", "answer_index", "accepted_answers", "explanation", "lesson_section", "updated_at") SELECT * FROM (VALUES
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'hoa-hop-chu-ngu-dong-tu'), 'choice', 'basic', 'The manager ___ the reports every Friday.', ARRAY['review', 'reviews', 'reviewing', 'have reviewed']::text[], 1::int, ARRAY[]::text[], 'Chủ ngữ số ít "The manager" → reviews.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'hoa-hop-chu-ngu-dong-tu'), 'choice', 'basic', 'Each of the employees ___ a laptop.', ARRAY['have', 'has', 'are having', 'having']::text[], 1::int, ARRAY[]::text[], '"Each of" → số ít: has.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'hoa-hop-chu-ngu-dong-tu'), 'choice', 'basic', 'The boxes in the storage room ___ heavy.', ARRAY['is', 'are', 'was', 'be']::text[], 1::int, ARRAY[]::text[], 'Chủ ngữ "The boxes" số nhiều → are.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'hoa-hop-chu-ngu-dong-tu'), 'choice', 'basic', 'Everyone ___ invited to the year-end party.', ARRAY['are', 'were', 'is', 'be']::text[], 2::int, ARRAY[]::text[], '"Everyone" → số ít: is.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'hoa-hop-chu-ngu-dong-tu'), 'fill', 'basic', 'The new printers ___ (be) faster than the old ones.', ARRAY[]::text[], NULL::int, ARRAY['are']::text[], 'Chủ ngữ số nhiều → are.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'hoa-hop-chu-ngu-dong-tu'), 'fill', 'basic', 'Information about the event ___ (be) available online.', ARRAY[]::text[], NULL::int, ARRAY['is']::text[], '"Information" không đếm được → is.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'hoa-hop-chu-ngu-dong-tu'), 'error', 'basic', 'The [[price]] of the tickets [[have]] [[increased]] [[recently]].', ARRAY[]::text[], 1::int, ARRAY[]::text[], 'Chủ ngữ thật là "price" → has.', 'mistakes', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'hoa-hop-chu-ngu-dong-tu'), 'choice', 'intermediate', 'The number of applications ___ doubled this year.', ARRAY['has', 'have', 'are', 'were']::text[], 0::int, ARRAY[]::text[], '"The number of" → số ít: has.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'hoa-hop-chu-ngu-dong-tu'), 'choice', 'intermediate', 'A number of customers ___ requested a catalog.', ARRAY['has', 'have', 'is', 'was']::text[], 1::int, ARRAY[]::text[], '"A number of" → số nhiều: have.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'hoa-hop-chu-ngu-dong-tu'), 'choice', 'intermediate', 'Neither the director nor the board members ___ aware of the issue.', ARRAY['was', 'is', 'were', 'has been']::text[], 2::int, ARRAY[]::text[], 'Chia theo danh từ gần "board members" → were.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'hoa-hop-chu-ngu-dong-tu'), 'choice', 'intermediate', 'The CEO, along with her assistants, ___ to arrive at noon.', ARRAY['expect', 'are expected', 'is expected', 'expecting']::text[], 2::int, ARRAY[]::text[], '"along with" → chia theo "The CEO": is expected.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'hoa-hop-chu-ngu-dong-tu'), 'fill', 'intermediate', 'Reviewing all the contracts ___ (take) at least two days.', ARRAY[]::text[], NULL::int, ARRAY['takes']::text[], 'V-ing làm chủ ngữ → số ít: takes.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'hoa-hop-chu-ngu-dong-tu'), 'fill', 'intermediate', 'One of our suppliers ___ (offer) free delivery.', ARRAY[]::text[], NULL::int, ARRAY['offers']::text[], '"One of" → số ít: offers.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'hoa-hop-chu-ngu-dong-tu'), 'error', 'intermediate', 'The [[results]] of the survey [[shows]] that customers [[prefer]] online [[ordering]].', ARRAY[]::text[], 1::int, ARRAY[]::text[], 'Chủ ngữ "results" số nhiều → show.', 'mistakes', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'hoa-hop-chu-ngu-dong-tu'), 'error', 'intermediate', 'Either the [[invoices]] or the [[receipt]] [[are]] [[missing]].', ARRAY[]::text[], 2::int, ARRAY[]::text[], 'Chia theo "receipt" (số ít) → is.', 'mistakes', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'hoa-hop-chu-ngu-dong-tu'), 'choice', 'advanced', 'The committee, which includes several experts, ___ its findings next week.', ARRAY['present', 'presents', 'will present', 'presenting']::text[], 2::int, ARRAY[]::text[], 'Chủ ngữ "The committee"; "next week" → will present.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'hoa-hop-chu-ngu-dong-tu'), 'choice', 'advanced', 'What the clients want ___ faster delivery.', ARRAY['are', 'is', 'were', 'be']::text[], 1::int, ARRAY[]::text[], 'Mệnh đề danh từ làm chủ ngữ → số ít: is.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'hoa-hop-chu-ngu-dong-tu'), 'choice', 'advanced', 'Not only the staff but also the manager ___ overtime this week.', ARRAY['work', 'works', 'are working', 'is working']::text[], 3::int, ARRAY[]::text[], '"Not only A but also B" chia theo B (số ít); "this week" → is working.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'hoa-hop-chu-ngu-dong-tu'), 'fill', 'advanced', 'Fifty dollars ___ (be) the maximum amount you can claim.', ARRAY[]::text[], NULL::int, ARRAY['is']::text[], 'Số tiền xem như một khối → số ít.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'hoa-hop-chu-ngu-dong-tu'), 'error', 'advanced', 'The [[quality]] of the components [[supplied]] by the two vendors [[vary]] [[considerably]].', ARRAY[]::text[], 2::int, ARRAY[]::text[], 'Chủ ngữ "quality" → varies.', 'mistakes', now())
INSERT INTO "grammar_topics" ("slug", "name", "group_name", "level", "sort_order", "summary", "lesson", "toeic_categories", "roadmap_labels", "updated_at") VALUES ('cau-bi-dong', 'Câu bị động', 'Động từ & thì', 'intermediate', 70, 'Nhận ra khi chủ ngữ "bị/được" tác động và chia be + V3 đúng thì.', '{"when_to_use":"Khi chủ ngữ không tự làm hành động mà chịu tác động (báo cáo được gửi, sản phẩm được giao). Dấu hiệu mạnh: sau chỗ trống KHÔNG có tân ngữ, hoặc có \"by + người làm\".","structure":"Công thức chung: S + be (chia theo thì) + V3.\n• Hiện tại đơn: am/is/are + V3\n• Quá khứ đơn: was/were + V3\n• Hiện tại hoàn thành: have/has been + V3\n• Tương lai / khuyết thiếu: will/can/must/should + be + V3\n• Tiếp diễn: am/is/are/was/were being + V3\nĐộng từ nội động (arrive, occur, happen, rise, remain) KHÔNG có dạng bị động.","examples":[{"en":"The packages were delivered this morning.","vi":"Các kiện hàng được giao sáng nay."},{"en":"All applications must be submitted by May 1.","vi":"Mọi hồ sơ phải được nộp trước 1/5."},{"en":"The lobby is being renovated this week.","vi":"Sảnh đang được sửa tuần này."},{"en":"The award has been given to Ms. Tran.","vi":"Giải đã được trao cho bà Trần."}],"mistakes":[{"wrong":"The meeting was happened yesterday.","right":"The meeting happened yesterday.","note":"\"happen\" là nội động từ, không bị động."},{"wrong":"The report will submit tomorrow.","right":"The report will be submitted tomorrow.","note":"Báo cáo không tự nộp → bị động."},{"wrong":"The products are ship overseas.","right":"The products are shipped overseas.","note":"Bị động cần V3."}],"signals":["Sau chỗ trống không có tân ngữ mà động từ là ngoại động từ (send, inform, require…) → bị động.","Có \"by + người/tổ chức\" → thường bị động.","Chủ ngữ là vật (report, order, product) + động từ hành động → nghĩ tới bị động."]}'::jsonb, ARRAY['verb_tense']::text[], ARRAY['Câu bị động']::text[], now()) ON CONFLICT ("slug") DO NOTHING;
INSERT INTO "grammar_formulas" ("topic_id", "sort_order", "pattern", "usage", "examples", "updated_at") SELECT * FROM (VALUES
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cau-bi-dong'), 0, 'S + be + V3 (+ by O)', 'Bị động chung; be chia theo thì.', '[{"en":"The contract was signed by both parties.","vi":"Hợp đồng được hai bên ký."}]'::jsonb, now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cau-bi-dong'), 1, 'S + will/can/must/should + be + V3', 'Bị động với tương lai và động từ khuyết thiếu.', '[{"en":"Late fees will be charged.","vi":"Sẽ tính phí trả chậm."}]'::jsonb, now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cau-bi-dong'), 2, 'S + have/has been + V3', 'Bị động hiện tại hoàn thành.', '[{"en":"The issue has been resolved.","vi":"Vấn đề đã được giải quyết."}]'::jsonb, now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cau-bi-dong'), 3, 'S + be being + V3', 'Bị động tiếp diễn.', '[{"en":"Your order is being processed.","vi":"Đơn của bạn đang được xử lý."}]'::jsonb, now())
INSERT INTO "grammar_exercises" ("topic_id", "kind", "level", "prompt", "options", "answer_index", "accepted_answers", "explanation", "lesson_section", "updated_at") SELECT * FROM (VALUES
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cau-bi-dong'), 'choice', 'basic', 'The office ___ every evening by a cleaning crew.', ARRAY['cleans', 'is cleaned', 'cleaning', 'has cleaning']::text[], 1::int, ARRAY[]::text[], 'Văn phòng "được" dọn, có "by" → is cleaned.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cau-bi-dong'), 'choice', 'basic', 'The letters ___ yesterday.', ARRAY['sent', 'were sent', 'are sending', 'send']::text[], 1::int, ARRAY[]::text[], 'Thư "được" gửi, "yesterday" → were sent.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cau-bi-dong'), 'choice', 'basic', 'English ___ in many countries.', ARRAY['speaks', 'is spoken', 'speaking', 'spoke']::text[], 1::int, ARRAY[]::text[], 'Tiếng Anh "được" nói → is spoken.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cau-bi-dong'), 'choice', 'basic', 'The meeting room must ___ before noon.', ARRAY['book', 'booked', 'be booked', 'booking']::text[], 2::int, ARRAY[]::text[], 'must + be + V3.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cau-bi-dong'), 'fill', 'basic', 'The new bridge ___ (build) in 2019.', ARRAY[]::text[], NULL::int, ARRAY['was built']::text[], 'Quá khứ, bị động → was built.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cau-bi-dong'), 'fill', 'basic', 'Breakfast ___ (serve) from 6 to 10 a.m. every day.', ARRAY[]::text[], NULL::int, ARRAY['is served']::text[], 'Thói quen, bị động → is served.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cau-bi-dong'), 'error', 'basic', 'The [[report]] [[was write]] by [[the]] [[analyst]].', ARRAY[]::text[], 1::int, ARRAY[]::text[], 'Bị động cần V3: was written.', 'mistakes', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cau-bi-dong'), 'choice', 'intermediate', 'All employees ___ to attend the safety training.', ARRAY['require', 'are required', 'requiring', 'have required']::text[], 1::int, ARRAY[]::text[], 'Nhân viên "được yêu cầu" → are required.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cau-bi-dong'), 'choice', 'intermediate', 'The results of the survey ___ next week.', ARRAY['announce', 'will announce', 'will be announced', 'are announcing']::text[], 2::int, ARRAY[]::text[], 'Kết quả "được công bố", "next week" → will be announced.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cau-bi-dong'), 'choice', 'intermediate', 'The construction of the new wing ___ by the end of the year.', ARRAY['completes', 'will complete', 'will be completed', 'is completing']::text[], 2::int, ARRAY[]::text[], 'Bị động tương lai.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cau-bi-dong'), 'choice', 'intermediate', 'Several improvements ___ since the last inspection.', ARRAY['made', 'have made', 'have been made', 'are making']::text[], 2::int, ARRAY[]::text[], '"since" + bị động → have been made.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cau-bi-dong'), 'fill', 'intermediate', 'Your order ___ (process) right now and will ship tomorrow.', ARRAY[]::text[], NULL::int, ARRAY['is being processed']::text[], '"right now" + bị động → is being processed.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cau-bi-dong'), 'fill', 'intermediate', 'Customers ___ (notify) by e-mail once the items have shipped.', ARRAY[]::text[], NULL::int, ARRAY['will be notified', 'are notified']::text[], 'Khách "được thông báo" → will be notified.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cau-bi-dong'), 'error', 'intermediate', 'The [[conference]] [[was occurred]] in the [[main]] [[hall]].', ARRAY[]::text[], 1::int, ARRAY[]::text[], '"occur" là nội động từ → occurred.', 'mistakes', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cau-bi-dong'), 'error', 'intermediate', 'All [[travel]] expenses [[must]] [[approve]] by the [[department head]].', ARRAY[]::text[], 2::int, ARRAY[]::text[], 'must + be + V3: be approved.', 'mistakes', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cau-bi-dong'), 'choice', 'advanced', 'The proposal is currently ___ by the legal team.', ARRAY['reviewing', 'reviewed', 'being reviewed', 'been reviewed']::text[], 2::int, ARRAY[]::text[], 'Bị động tiếp diễn: is being reviewed.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cau-bi-dong'), 'choice', 'advanced', 'Visitors are asked ___ their badges at all times.', ARRAY['wear', 'to wear', 'wearing', 'worn']::text[], 1::int, ARRAY[]::text[], '"be asked + to V".', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cau-bi-dong'), 'choice', 'advanced', 'Had the error ___ earlier, the shipment would not have been delayed.', ARRAY['notice', 'noticing', 'been noticed', 'noticed']::text[], 2::int, ARRAY[]::text[], 'Đảo ngữ câu điều kiện loại 3: Had + S + V3. Lỗi "được" phát hiện (bị động) → Had the error been noticed.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cau-bi-dong'), 'fill', 'advanced', 'The applicants ___ (expect) to have at least three years of experience.', ARRAY[]::text[], NULL::int, ARRAY['are expected']::text[], '"be expected to" = được kỳ vọng.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cau-bi-dong'), 'error', 'advanced', 'The [[budget]] [[had]] already [[approved]] when the [[new figures]] arrived.', ARRAY[]::text[], 1::int, ARRAY[]::text[], 'Ngân sách "được duyệt" → had already been approved.', 'mistakes', now())
INSERT INTO "grammar_topics" ("slug", "name", "group_name", "level", "sort_order", "summary", "lesson", "toeic_categories", "roadmap_labels", "updated_at") VALUES ('danh-dong-tu-dong-tu-nguyen-mau', 'Danh động từ và động từ nguyên mẫu', 'Động từ & thì', 'intermediate', 80, 'Động từ nào đi với V-ing, động từ nào đi với to V; V-ing sau giới từ.', '{"when_to_use":"Khi 4 lựa chọn có to V, V-ing, V nguyên mẫu, V3. Nhìn động từ hoặc giới từ đứng ngay trước chỗ trống.","structure":"• Sau giới từ (in, on, for, by, before, after, without, about) → V-ing.\n• Động từ + to V: plan, decide, agree, want, hope, expect, need, offer, refuse, promise, afford, manage, fail.\n• Động từ + V-ing: consider, avoid, suggest, recommend, finish, enjoy, mind, keep, postpone, delay, discuss, risk.\n• Động từ + O + to V: ask, allow, encourage, require, remind, invite, advise, enable.\n• \"look forward to / be committed to / be used to / object to\" + V-ing (to là giới từ).\n• Mục đích: (in order) to V.","examples":[{"en":"We plan to launch the product in June.","vi":"Chúng tôi dự định ra mắt vào tháng Sáu."},{"en":"Please avoid using your phone during the seminar.","vi":"Tránh dùng điện thoại trong buổi hội thảo."},{"en":"Thank you for submitting your application.","vi":"Cảm ơn bạn đã nộp hồ sơ."},{"en":"We look forward to working with you.","vi":"Mong được làm việc với bạn."}],"mistakes":[{"wrong":"We look forward to meet you.","right":"We look forward to meeting you.","note":"\"look forward to\" + V-ing."},{"wrong":"She suggested to change the date.","right":"She suggested changing the date.","note":"\"suggest\" + V-ing."},{"wrong":"He decided postponing the trip.","right":"He decided to postpone the trip.","note":"\"decide\" + to V."}],"signals":["Giới từ ngay trước chỗ trống → V-ing.","Động từ chỉ dự định, mong muốn (plan, hope, want, decide) → to V.","Động từ chỉ cân nhắc, tránh, hoàn thành (consider, avoid, finish) → V-ing.","\"in order ___\" / chỉ mục đích → to V."]}'::jsonb, ARRAY['verb_tense']::text[], ARRAY['Danh động từ và động từ nguyên mẫu']::text[], now()) ON CONFLICT ("slug") DO NOTHING;
INSERT INTO "grammar_formulas" ("topic_id", "sort_order", "pattern", "usage", "examples", "updated_at") SELECT * FROM (VALUES
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'danh-dong-tu-dong-tu-nguyen-mau'), 0, 'preposition + V-ing', 'Sau giới từ luôn là V-ing.', '[{"en":"before leaving the office","vi":"trước khi rời văn phòng"}]'::jsonb, now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'danh-dong-tu-dong-tu-nguyen-mau'), 1, 'plan/decide/agree/hope/need + to V', 'Động từ đi với to V.', '[{"en":"They agreed to extend the deadline.","vi":"Họ đồng ý gia hạn."}]'::jsonb, now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'danh-dong-tu-dong-tu-nguyen-mau'), 2, 'consider/avoid/suggest/finish/recommend + V-ing', 'Động từ đi với V-ing.', '[{"en":"We recommend booking early.","vi":"Nên đặt sớm."}]'::jsonb, now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'danh-dong-tu-dong-tu-nguyen-mau'), 3, 'ask/allow/require/encourage + O + to V', 'Động từ + tân ngữ + to V.', '[{"en":"The policy allows staff to work remotely.","vi":"Chính sách cho phép làm từ xa."}]'::jsonb, now())
INSERT INTO "grammar_exercises" ("topic_id", "kind", "level", "prompt", "options", "answer_index", "accepted_answers", "explanation", "lesson_section", "updated_at") SELECT * FROM (VALUES
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'danh-dong-tu-dong-tu-nguyen-mau'), 'choice', 'basic', 'We hope ___ the project by June.', ARRAY['finish', 'finishing', 'to finish', 'finished']::text[], 2::int, ARRAY[]::text[], '"hope" + to V.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'danh-dong-tu-dong-tu-nguyen-mau'), 'choice', 'basic', 'Thank you for ___ our store.', ARRAY['visit', 'to visit', 'visiting', 'visited']::text[], 2::int, ARRAY[]::text[], 'Sau giới từ "for" → V-ing.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'danh-dong-tu-dong-tu-nguyen-mau'), 'choice', 'basic', 'Mr. Lim finished ___ the report at 5 p.m.', ARRAY['write', 'to write', 'writing', 'written']::text[], 2::int, ARRAY[]::text[], '"finish" + V-ing.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'danh-dong-tu-dong-tu-nguyen-mau'), 'choice', 'basic', 'She went to the bank ___ some money.', ARRAY['withdraw', 'to withdraw', 'withdrawing', 'withdrawn']::text[], 1::int, ARRAY[]::text[], 'Chỉ mục đích → to withdraw.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'danh-dong-tu-dong-tu-nguyen-mau'), 'fill', 'basic', 'The manager agreed ___ (meet) the clients on Friday.', ARRAY[]::text[], NULL::int, ARRAY['to meet']::text[], '"agree" + to V.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'danh-dong-tu-dong-tu-nguyen-mau'), 'fill', 'basic', 'Please avoid ___ (park) in front of the entrance.', ARRAY[]::text[], NULL::int, ARRAY['parking']::text[], '"avoid" + V-ing.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'danh-dong-tu-dong-tu-nguyen-mau'), 'error', 'basic', 'We are [[interested]] in [[hire]] [[more]] [[staff]].', ARRAY[]::text[], 1::int, ARRAY[]::text[], 'Sau giới từ "in" → hiring.', 'mistakes', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'danh-dong-tu-dong-tu-nguyen-mau'), 'choice', 'intermediate', 'The company is considering ___ a new office in Da Nang.', ARRAY['open', 'to open', 'opening', 'opened']::text[], 2::int, ARRAY[]::text[], '"consider" + V-ing.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'danh-dong-tu-dong-tu-nguyen-mau'), 'choice', 'intermediate', 'The new system enables employees ___ their hours online.', ARRAY['record', 'to record', 'recording', 'recorded']::text[], 1::int, ARRAY[]::text[], '"enable + O + to V".', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'danh-dong-tu-dong-tu-nguyen-mau'), 'choice', 'intermediate', 'We look forward to ___ from you soon.', ARRAY['hear', 'hearing', 'heard', 'be heard']::text[], 1::int, ARRAY[]::text[], '"look forward to" + V-ing.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'danh-dong-tu-dong-tu-nguyen-mau'), 'choice', 'intermediate', 'Ms. Ford recommended ___ the meeting until next week.', ARRAY['postpone', 'to postpone', 'postponing', 'postponed']::text[], 2::int, ARRAY[]::text[], '"recommend" + V-ing.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'danh-dong-tu-dong-tu-nguyen-mau'), 'fill', 'intermediate', 'The firm failed ___ (meet) its sales target.', ARRAY[]::text[], NULL::int, ARRAY['to meet']::text[], '"fail" + to V.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'danh-dong-tu-dong-tu-nguyen-mau'), 'fill', 'intermediate', 'Staff are encouraged ___ (share) their ideas.', ARRAY[]::text[], NULL::int, ARRAY['to share']::text[], '"be encouraged + to V".', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'danh-dong-tu-dong-tu-nguyen-mau'), 'error', 'intermediate', 'The [[team]] is [[committed]] to [[deliver]] high-quality [[service]].', ARRAY[]::text[], 2::int, ARRAY[]::text[], '"be committed to" + V-ing: delivering.', 'mistakes', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'danh-dong-tu-dong-tu-nguyen-mau'), 'error', 'intermediate', 'Customers can [[save]] money by [[to book]] [[their]] tickets [[online]].', ARRAY[]::text[], 1::int, ARRAY[]::text[], 'Sau giới từ "by" → booking.', 'mistakes', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'danh-dong-tu-dong-tu-nguyen-mau'), 'choice', 'advanced', 'Instead of ___ a new printer, we repaired the old one.', ARRAY['buy', 'to buy', 'buying', 'bought']::text[], 2::int, ARRAY[]::text[], '"Instead of" + V-ing.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'danh-dong-tu-dong-tu-nguyen-mau'), 'choice', 'advanced', 'The CEO is used to ___ long hours.', ARRAY['work', 'working', 'worked', 'be worked']::text[], 1::int, ARRAY[]::text[], '"be used to" (quen với) + V-ing.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'danh-dong-tu-dong-tu-nguyen-mau'), 'choice', 'advanced', 'The board refused ___ the merger without further review.', ARRAY['approving', 'approve', 'to approve', 'approval']::text[], 2::int, ARRAY[]::text[], '"refuse" + to V.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'danh-dong-tu-dong-tu-nguyen-mau'), 'fill', 'advanced', 'The guidelines are intended to help managers avoid ___ (make) costly errors.', ARRAY[]::text[], NULL::int, ARRAY['making']::text[], '"avoid" + V-ing.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'danh-dong-tu-dong-tu-nguyen-mau'), 'error', 'advanced', 'The [[supervisor]] [[reminded]] all staff [[submitting]] their [[timesheets]].', ARRAY[]::text[], 2::int, ARRAY[]::text[], '"remind + O + to V": to submit.', 'mistakes', now())
INSERT INTO "grammar_topics" ("slug", "name", "group_name", "level", "sort_order", "summary", "lesson", "toeic_categories", "roadmap_labels", "updated_at") VALUES ('phan-tu-lam-tinh-tu', 'Phân từ V-ing / V3 dùng như tính từ', 'Động từ & thì', 'intermediate', 90, 'Phân biệt -ing (chủ động, gây ra cảm xúc) và -ed/V3 (bị động, chịu cảm xúc) khi đứng trước danh từ hoặc sau be.', '{"when_to_use":"Khi các lựa chọn có cả dạng -ing và -ed của cùng động từ (interesting / interested, attached / attaching) và chỗ trống ở vị trí tính từ.","structure":"• V-ing: mang nghĩa chủ động, hoặc gây ra cảm xúc (an exciting offer — ưu đãi gây hứng thú; the remaining items — món còn lại).\n• V3/-ed: mang nghĩa bị động, hoặc người chịu cảm xúc (excited customers — khách hào hứng; the attached file — tệp được đính kèm).\n• Cụm hay gặp: attached document, enclosed form, revised schedule, qualified candidates, experienced staff, updated version, limited time; existing customers, leading company, growing demand, upcoming event, missing item.","examples":[{"en":"Please review the attached file.","vi":"Vui lòng xem tệp đính kèm."},{"en":"The results were disappointing.","vi":"Kết quả gây thất vọng."},{"en":"The disappointed investors left early.","vi":"Nhà đầu tư thất vọng về sớm."},{"en":"We are hiring experienced engineers.","vi":"Chúng tôi tuyển kỹ sư có kinh nghiệm."}],"mistakes":[{"wrong":"I am very interesting in the job.","right":"I am very interested in the job.","note":"Người chịu cảm xúc → -ed."},{"wrong":"Please see the enclosing brochure.","right":"Please see the enclosed brochure.","note":"Tờ rơi \"được\" kèm theo → enclosed."},{"wrong":"The tour was very excited.","right":"The tour was very exciting.","note":"Chuyến đi gây hứng thú → -ing."}],"signals":["Danh từ là người cảm thấy → -ed; danh từ là vật gây ra cảm xúc → -ing.","Danh từ được tác động (file, form, schedule) → -ed.","Danh từ tự làm hành động (demand grows → growing demand) → -ing."]}'::jsonb, ARRAY['word_form']::text[], ARRAY['Phân từ hiện tại / quá khứ dùng như tính từ']::text[], now()) ON CONFLICT ("slug") DO NOTHING;
INSERT INTO "grammar_formulas" ("topic_id", "sort_order", "pattern", "usage", "examples", "updated_at") SELECT * FROM (VALUES
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'phan-tu-lam-tinh-tu'), 0, 'V-ing + N', 'Danh từ thực hiện hành động / gây cảm xúc.', '[{"en":"rising costs, a confusing message","vi":"chi phí tăng, tin nhắn khó hiểu"}]'::jsonb, now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'phan-tu-lam-tinh-tu'), 1, 'V3 + N', 'Danh từ chịu tác động / người có cảm xúc.', '[{"en":"the revised plan, satisfied clients","vi":"kế hoạch đã sửa, khách hài lòng"}]'::jsonb, now())
