  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'phan-tu-lam-tinh-tu'), 'choice', 'basic', 'The ___ customers received a full refund.', ARRAY['satisfying', 'satisfied', 'satisfy', 'satisfaction']::text[], 1::int, ARRAY[]::text[], 'Khách hàng cảm thấy hài lòng → satisfied.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'phan-tu-lam-tinh-tu'), 'choice', 'basic', 'Please fill out the ___ form.', ARRAY['attaching', 'attached', 'attach', 'attachment']::text[], 1::int, ARRAY[]::text[], 'Mẫu đơn "được" đính kèm → attached.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'phan-tu-lam-tinh-tu'), 'choice', 'basic', 'We had a very ___ day at the trade fair.', ARRAY['tired', 'tiring', 'tire', 'tiredness']::text[], 1::int, ARRAY[]::text[], 'Ngày làm người ta mệt → tiring.', 'structure', now()),
