  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'phan-tu-lam-tinh-tu'), 'fill', 'basic', 'The news about the merger was ___ (shock).', ARRAY[]::text[], NULL::int, ARRAY['shocking']::text[], 'Tin gây sốc → shocking.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'phan-tu-lam-tinh-tu'), 'error', 'basic', 'I was [[very]] [[boring]] during the [[long]] [[lecture]].', ARRAY[]::text[], 1::int, ARRAY[]::text[], 'Người cảm thấy chán → bored.', 'mistakes', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'phan-tu-lam-tinh-tu'), 'choice', 'intermediate', 'The company is looking for ___ candidates with sales experience.', ARRAY['qualify', 'qualifying', 'qualified', 'qualification']::text[], 2::int, ARRAY[]::text[], 'Ứng viên đủ tiêu chuẩn → qualified.', 'structure', now()),
