  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'phan-tu-lam-tinh-tu'), 'choice', 'intermediate', 'Discounts are available to all ___ customers.', ARRAY['exist', 'existing', 'existed', 'existence']::text[], 1::int, ARRAY[]::text[], '"existing customers" = khách hiện có.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'phan-tu-lam-tinh-tu'), 'fill', 'intermediate', 'The ___ (remain) tickets will be sold at the door.', ARRAY[]::text[], NULL::int, ARRAY['remaining']::text[], 'Vé còn lại → remaining.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'phan-tu-lam-tinh-tu'), 'fill', 'intermediate', 'The offer is valid for a ___ (limit) time only.', ARRAY[]::text[], NULL::int, ARRAY['limited']::text[], 'Thời gian "bị" giới hạn → limited.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'phan-tu-lam-tinh-tu'), 'error', 'intermediate', 'Please [[return]] the [[signing]] contract [[by]] [[Friday]].', ARRAY[]::text[], 1::int, ARRAY[]::text[], 'Hợp đồng "đã được" ký → signed.', 'mistakes', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'phan-tu-lam-tinh-tu'), 'error', 'intermediate', 'The [[upcoming]] event will feature several [[leaded]] [[industry]] [[experts]].', ARRAY[]::text[], 1::int, ARRAY[]::text[], 'Chuyên gia hàng đầu → leading.', 'mistakes', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'phan-tu-lam-tinh-tu'), 'choice', 'advanced', 'Investors were ___ by the unexpectedly strong earnings.', ARRAY['encouraging', 'encouraged', 'encourage', 'encouragement']::text[], 1::int, ARRAY[]::text[], 'Nhà đầu tư cảm thấy được khích lệ → encouraged.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'phan-tu-lam-tinh-tu'), 'choice', 'advanced', 'The ___ items should be reported to the front desk.', ARRAY['missed', 'missing', 'miss', 'misses']::text[], 1::int, ARRAY[]::text[], '"missing items" = đồ bị thất lạc.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'phan-tu-lam-tinh-tu'), 'choice', 'advanced', 'Only ___ personnel may enter the server room.', ARRAY['authorizing', 'authorized', 'authorize', 'authorization']::text[], 1::int, ARRAY[]::text[], 'Nhân sự "được" cấp phép → authorized.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'phan-tu-lam-tinh-tu'), 'fill', 'advanced', 'The survey results were somewhat ___ (disappoint) for the marketing team.', ARRAY[]::text[], NULL::int, ARRAY['disappointing']::text[], 'Kết quả gây thất vọng → disappointing.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'phan-tu-lam-tinh-tu'), 'error', 'advanced', 'The [[newly]] [[renovating]] hotel offers [[spacious]] rooms at [[affordable]] rates.', ARRAY[]::text[], 1::int, ARRAY[]::text[], 'Khách sạn "đã được" sửa → renovated.', 'mistakes', now())
INSERT INTO "grammar_topics" ("slug", "name", "group_name", "level", "sort_order", "summary", "lesson", "toeic_categories", "roadmap_labels", "updated_at") VALUES ('so-sanh', 'So sánh hơn, so sánh nhất', 'Tính từ & trạng từ', 'intermediate', 100, 'So sánh hơn với than, so sánh nhất với the, so sánh bằng as … as và các từ nhấn mạnh.', '{"when_to_use":"Khi lựa chọn có -er / -est / more / most / as. Dấu hiệu: \"than\" → so sánh hơn; \"the … of/in\" hoặc \"ever\" → so sánh nhất; \"as … as\" → so sánh bằng.","structure":"• Tính từ ngắn: -er / the -est (cheaper, the cheapest). Tính từ dài: more / the most (more efficient, the most efficient).\n• Bất quy tắc: good–better–the best; bad–worse–the worst; far–farther/further; many/much–more–the most; little–less–the least.\n• So sánh bằng: as + adj/adv + as; not as/so … as.\n• Nhấn mạnh so sánh hơn: much, far, even, significantly, considerably + so sánh hơn (KHÔNG dùng very).\n• The + so sánh hơn …, the + so sánh hơn … (càng … càng …).","examples":[{"en":"This model is much lighter than the previous one.","vi":"Mẫu này nhẹ hơn nhiều so với mẫu trước."},{"en":"It was the most successful campaign in our history.","vi":"Đó là chiến dịch thành công nhất."},{"en":"Our prices are as low as our competitors'' prices.","vi":"Giá của chúng tôi thấp bằng đối thủ."},{"en":"The sooner you apply, the better your chances.","vi":"Nộp càng sớm cơ hội càng cao."}],"mistakes":[{"wrong":"This is more cheaper than that.","right":"This is cheaper than that.","note":"Không dùng more với -er."},{"wrong":"It is very better now.","right":"It is much better now.","note":"Nhấn mạnh so sánh hơn dùng much/far."},{"wrong":"She is the most good employee.","right":"She is the best employee.","note":"good → the best."}],"signals":["Có \"than\" phía sau → so sánh hơn.","Có \"the\" phía trước và \"of all / in the company / ever\" → so sánh nhất.","Có \"as\" phía trước chỗ trống và \"as\" phía sau → nguyên dạng."]}'::jsonb, ARRAY['word_form']::text[], ARRAY['So sánh hơn và so sánh nhất']::text[], now()) ON CONFLICT ("slug") DO NOTHING;
