  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'so-sanh'), 1, 'the + adj-est / the most + adj (+ of/in …)', 'So sánh nhất.', '[{"en":"the largest supplier in Asia","vi":"nhà cung cấp lớn nhất châu Á"}]'::jsonb, now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'so-sanh'), 2, 'as + adj/adv + as', 'So sánh bằng.', '[{"en":"as soon as possible","vi":"càng sớm càng tốt"}]'::jsonb, now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'so-sanh'), 3, 'The + so sánh hơn + S + V, the + so sánh hơn + S + V', 'Càng … càng …', '[{"en":"The more you practice, the better you get.","vi":""}]'::jsonb, now())
