  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'so-sanh'), 'choice', 'basic', 'This is the ___ hotel in the city.', ARRAY['expensive', 'more expensive', 'most expensive', 'expensiver']::text[], 2::int, ARRAY[]::text[], '"the … in the city" → most expensive.', 'structure', now()),
