  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'so-sanh'), 'error', 'basic', 'This [[route]] is [[more short]] [[than]] the [[highway]].', ARRAY[]::text[], 1::int, ARRAY[]::text[], 'Tính từ ngắn → shorter.', 'mistakes', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'so-sanh'), 'choice', 'intermediate', 'Sales this quarter were ___ higher than we had predicted.', ARRAY['significant', 'significantly', 'significance', 'signify']::text[], 1::int, ARRAY[]::text[], 'Nhấn mạnh so sánh hơn bằng trạng từ significantly.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'so-sanh'), 'choice', 'intermediate', 'Of all the applicants, Mr. Diaz is the ___ qualified.', ARRAY['more', 'most', 'much', 'many']::text[], 1::int, ARRAY[]::text[], '"Of all" → the most.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'so-sanh'), 'choice', 'intermediate', 'The new process is not as ___ as we had hoped.', ARRAY['efficient', 'more efficient', 'most efficient', 'efficiently']::text[], 0::int, ARRAY[]::text[], '"as … as" sau "is" → tính từ nguyên dạng.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'so-sanh'), 'choice', 'intermediate', 'The ___ we finish, the sooner we can leave.', ARRAY['early', 'earlier', 'earliest', 'most early']::text[], 1::int, ARRAY[]::text[], '"The + so sánh hơn" → earlier.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'so-sanh'), 'fill', 'intermediate', 'This year''s conference attracted ___ (many) participants than ever before.', ARRAY[]::text[], NULL::int, ARRAY['more']::text[], 'many → more.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'so-sanh'), 'fill', 'intermediate', 'The second proposal is ___ (little) costly than the first.', ARRAY[]::text[], NULL::int, ARRAY['less']::text[], 'little → less.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'so-sanh'), 'error', 'intermediate', 'It was the [[most]] [[busy]] [[week]] of the [[year]].', ARRAY[]::text[], 1::int, ARRAY[]::text[], 'Tính từ hai âm tiết tận cùng -y → busiest (the busiest).', 'mistakes', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'so-sanh'), 'error', 'intermediate', 'Our [[prices]] are [[as]] competitive [[than]] [[those]] of larger stores.', ARRAY[]::text[], 2::int, ARRAY[]::text[], 'So sánh bằng: as … as.', 'mistakes', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'so-sanh'), 'choice', 'advanced', 'The revised budget is considerably ___ than the original.', ARRAY['realistic', 'more realistic', 'most realistic', 'realistically']::text[], 1::int, ARRAY[]::text[], '"than" + tính từ dài → more realistic.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'so-sanh'), 'choice', 'advanced', 'This is by far the ___ response we have received.', ARRAY['positive', 'more positive', 'most positive', 'positively']::text[], 2::int, ARRAY[]::text[], '"by far" nhấn mạnh so sánh nhất.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'so-sanh'), 'choice', 'advanced', 'The more carefully you plan, the ___ problems you will face.', ARRAY['few', 'fewer', 'fewest', 'less']::text[], 1::int, ARRAY[]::text[], '"problems" đếm được → fewer.', 'structure', now()),
