INSERT INTO "grammar_topics" ("slug", "name", "group_name", "level", "sort_order", "summary", "lesson", "toeic_categories", "roadmap_labels", "updated_at") VALUES ('gioi-tu', 'Giới từ thời gian, nơi chốn, cụm cố định', 'Giới từ & liên từ', 'basic', 110, 'in/on/at, by/until, for/during/within và các cụm giới từ cố định hay gặp trong TOEIC.', '{"when_to_use":"Khi 4 lựa chọn đều là giới từ. Xem danh từ phía sau (thời điểm, khoảng thời gian, nơi chốn) và động từ/tính từ phía trước (cụm cố định).","structure":"Thời gian: at + giờ (at 9 a.m.), on + ngày/thứ (on Monday, on May 5), in + tháng/năm/buổi (in June, in 2025, in the morning).\n• by + mốc (trước/không muộn hơn): submit by Friday. until + mốc (kéo dài đến): open until 9 p.m.\n• for + khoảng thời gian; during + danh từ sự kiện (during the meeting); within + khoảng (within 3 days).\nNơi chốn: at + điểm (at the front desk), on + bề mặt/tầng (on the third floor), in + không gian (in the lobby).\nCụm cố định: responsible for, interested in, in charge of, according to, due to, in addition to, prior to, regardless of, on behalf of, in response to.","examples":[{"en":"The meeting starts at 10 a.m. on Monday.","vi":"Cuộc họp bắt đầu 10 giờ sáng thứ Hai."},{"en":"Please submit the report by Friday.","vi":"Nộp báo cáo trước thứ Sáu."},{"en":"The store is open until 9 p.m.","vi":"Cửa hàng mở đến 9 giờ tối."},{"en":"Refunds are issued within 14 days.","vi":"Hoàn tiền trong vòng 14 ngày."}],"mistakes":[{"wrong":"The office is closed in Sunday.","right":"The office is closed on Sunday.","note":"Thứ trong tuần → on."},{"wrong":"Please reply until Friday.","right":"Please reply by Friday.","note":"Hạn chót → by."},{"wrong":"He slept for the presentation.","right":"He slept during the presentation.","note":"Trong suốt sự kiện → during."}],"signals":["Giờ → at; ngày/thứ → on; tháng/năm → in.","Hạn chót → by; kéo dài tới → until.","Danh từ sự kiện (meeting, flight) → during; con số thời gian (3 days) → for/within.","Danh từ/cụm danh từ phía sau (không phải mệnh đề) → giới từ, không phải liên từ."]}'::jsonb, ARRAY['prep_conj']::text[], ARRAY['Giới từ chỉ thời gian và nơi chốn (in/on/at)', 'Liên từ và giới từ thường gặp trong Part 5']::text[], now()) ON CONFLICT ("slug") DO NOTHING;
