  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'gioi-tu'), 2, 'for + khoảng | during + sự kiện | within + khoảng', 'Giới từ khoảng thời gian.', '[{"en":"within two weeks","vi":"trong vòng hai tuần"}]'::jsonb, now())
