  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'gioi-tu'), 'fill', 'basic', 'The store will be closed ___ two weeks for renovation. (for/during)', ARRAY[]::text[], NULL::int, ARRAY['for']::text[], 'Khoảng thời gian → for.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'gioi-tu'), 'fill', 'basic', 'Applications must be received ___ May 15. (by/until)', ARRAY[]::text[], NULL::int, ARRAY['by']::text[], 'Hạn chót → by.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'gioi-tu'), 'error', 'basic', 'The [[meeting]] [[has been]] moved [[at]] [[Thursday]].', ARRAY[]::text[], 2::int, ARRAY[]::text[], 'Thứ → to/on Thursday; "moved to Thursday".', 'mistakes', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'gioi-tu'), 'choice', 'intermediate', 'Ms. Grant is responsible ___ training new staff.', ARRAY['of', 'for', 'to', 'with']::text[], 1::int, ARRAY[]::text[], '"responsible for".', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'gioi-tu'), 'choice', 'intermediate', 'The flight was delayed ___ heavy fog.', ARRAY['because', 'due to', 'although', 'so that']::text[], 1::int, ARRAY[]::text[], 'Sau là cụm danh từ → due to (giới từ).', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'gioi-tu'), 'choice', 'intermediate', 'The library is open ___ 10 p.m. on weekdays.', ARRAY['by', 'until', 'within', 'since']::text[], 1::int, ARRAY[]::text[], 'Kéo dài tới → until.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'gioi-tu'), 'choice', 'intermediate', 'Customers will receive a reply ___ 24 hours.', ARRAY['within', 'during', 'since', 'among']::text[], 0::int, ARRAY[]::text[], '"within 24 hours" = trong vòng.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'gioi-tu'), 'fill', 'intermediate', 'Mr. Bose spoke ___ behalf of the entire team.', ARRAY[]::text[], NULL::int, ARRAY['on']::text[], '"on behalf of".', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'gioi-tu'), 'fill', 'intermediate', '___ addition to the salary, employees receive a bonus.', ARRAY[]::text[], NULL::int, ARRAY['In']::text[], '"In addition to".', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'gioi-tu'), 'error', 'intermediate', 'All visitors must [[sign]] in [[at]] the front desk [[prior]] [[of]] entering.', ARRAY[]::text[], 3::int, ARRAY[]::text[], '"prior to".', 'mistakes', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'gioi-tu'), 'error', 'intermediate', 'The [[package]] was [[delivered]] [[on]] the [[morning]].', ARRAY[]::text[], 2::int, ARRAY[]::text[], 'Buổi sáng (không có ngày cụ thể) → in the morning.', 'mistakes', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'gioi-tu'), 'choice', 'advanced', '___ the economic downturn, the company recorded a profit.', ARRAY['Although', 'Despite', 'Because', 'However']::text[], 1::int, ARRAY[]::text[], 'Sau là cụm danh từ, nghĩa tương phản → Despite.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'gioi-tu'), 'choice', 'advanced', 'Fees will be refunded ___ of the reason for cancellation.', ARRAY['regardless', 'instead', 'because', 'in spite']::text[], 0::int, ARRAY[]::text[], '"regardless of" = bất kể.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'gioi-tu'), 'fill', 'advanced', 'The new policy will take effect ___ January 1.', ARRAY[]::text[], NULL::int, ARRAY['on', 'from', 'as of']::text[], '"take effect on/from/as of + ngày".', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'gioi-tu'), 'error', 'advanced', '[[According]] [[with]] the [[report]], sales rose by 12% [[in]] the third quarter.', ARRAY[]::text[], 1::int, ARRAY[]::text[], '"According to".', 'mistakes', now())
INSERT INTO "grammar_topics" ("slug", "name", "group_name", "level", "sort_order", "summary", "lesson", "toeic_categories", "roadmap_labels", "updated_at") VALUES ('lien-tu-trang-tu-lien-ket', 'Liên từ và trạng từ liên kết', 'Giới từ & liên từ', 'intermediate', 120, 'Phân biệt liên từ (although, because), giới từ (despite, because of) và trạng từ liên kết (however, therefore).', '{"when_to_use":"Khi lựa chọn trộn liên từ, giới từ và trạng từ liên kết có nghĩa gần nhau (although / despite / however). Xét 2 điều: phía sau là mệnh đề hay cụm danh từ, và quan hệ ý nghĩa (tương phản, nguyên nhân, kết quả, điều kiện).","structure":"• Liên từ + MỆNH ĐỀ (S + V): although, though, because, since, while, whereas, unless, if, once, as soon as, so that, provided that.\n• Giới từ + CỤM DANH TỪ / V-ing: despite, in spite of, because of, due to, owing to, during, without.\n• Trạng từ liên kết nối HAI CÂU, thường có dấu chấm/chấm phẩy và dấu phẩy: however, therefore, moreover, furthermore, consequently, nevertheless, otherwise, meanwhile.\n• Cặp liên từ: both … and, either … or, neither … nor, not only … but also.","examples":[{"en":"Although it rained, the event continued.","vi":"Dù trời mưa, sự kiện vẫn tiếp tục."},{"en":"Despite the rain, the event continued.","vi":"Bất chấp mưa, sự kiện vẫn tiếp tục."},{"en":"Sales fell; however, profits rose.","vi":"Doanh số giảm; tuy nhiên lợi nhuận tăng."},{"en":"You can pay either by card or in cash.","vi":"Có thể trả bằng thẻ hoặc tiền mặt."}],"mistakes":[{"wrong":"Despite it was late, we continued.","right":"Although it was late, we continued.","note":"Sau là mệnh đề → although."},{"wrong":"Because of the weather was bad, …","right":"Because the weather was bad, …","note":"\"because of\" + cụm danh từ."},{"wrong":"Neither the manager or the staff knew.","right":"Neither the manager nor the staff knew.","note":"neither … nor."}],"signals":["Phía sau có động từ chia → liên từ; chỉ có danh từ → giới từ.","Chỗ trống ngay sau dấu chấm phẩy / đầu câu có dấu phẩy sau → trạng từ liên kết.","Thấy \"either / neither / both / not only\" ở trước → tìm cặp đi kèm."]}'::jsonb, ARRAY['prep_conj']::text[], ARRAY['Liên từ và giới từ thường gặp trong Part 5']::text[], now()) ON CONFLICT ("slug") DO NOTHING;
INSERT INTO "grammar_formulas" ("topic_id", "sort_order", "pattern", "usage", "examples", "updated_at") SELECT * FROM (VALUES
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'lien-tu-trang-tu-lien-ket'), 0, 'Although/Because/Unless + S + V, S + V', 'Liên từ nối mệnh đề.', '[{"en":"Unless you register, you cannot attend.","vi":"Không đăng ký thì không được dự."}]'::jsonb, now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'lien-tu-trang-tu-lien-ket'), 1, 'Despite/Because of/Due to + N/V-ing', 'Giới từ + cụm danh từ.', '[{"en":"Because of the delay, we missed the train.","vi":""}]'::jsonb, now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'lien-tu-trang-tu-lien-ket'), 2, 'S + V; however/therefore, S + V.', 'Trạng từ liên kết nối hai câu.', '[{"en":"The price rose; therefore, demand fell.","vi":""}]'::jsonb, now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'lien-tu-trang-tu-lien-ket'), 3, 'both A and B | either A or B | neither A nor B | not only A but also B', 'Cặp liên từ.', '[{"en":"not only fast but also reliable","vi":""}]'::jsonb, now())
INSERT INTO "grammar_exercises" ("topic_id", "kind", "level", "prompt", "options", "answer_index", "accepted_answers", "explanation", "lesson_section", "updated_at") SELECT * FROM (VALUES
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'lien-tu-trang-tu-lien-ket'), 'choice', 'basic', '___ the train was late, we missed the meeting.', ARRAY['Because', 'Because of', 'Despite', 'However']::text[], 0::int, ARRAY[]::text[], 'Sau là mệnh đề, nghĩa nguyên nhân → Because.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'lien-tu-trang-tu-lien-ket'), 'choice', 'basic', 'The office was closed ___ the holiday.', ARRAY['because', 'because of', 'although', 'so']::text[], 1::int, ARRAY[]::text[], 'Sau là cụm danh từ → because of.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'lien-tu-trang-tu-lien-ket'), 'choice', 'basic', 'You can contact us ___ by phone or by e-mail.', ARRAY['both', 'either', 'neither', 'not only']::text[], 1::int, ARRAY[]::text[], '"either … or".', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'lien-tu-trang-tu-lien-ket'), 'choice', 'basic', 'The hotel is small, ___ it is very comfortable.', ARRAY['but', 'because', 'so', 'or']::text[], 0::int, ARRAY[]::text[], 'Tương phản → but.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'lien-tu-trang-tu-lien-ket'), 'fill', 'basic', 'Mr. Park was tired, ___ he kept working. (but/so)', ARRAY[]::text[], NULL::int, ARRAY['but']::text[], 'Tương phản → but.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'lien-tu-trang-tu-lien-ket'), 'fill', 'basic', 'Both the manager ___ the assistant attended. (and/or)', ARRAY[]::text[], NULL::int, ARRAY['and']::text[], '"both … and".', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'lien-tu-trang-tu-lien-ket'), 'error', 'basic', '[[Despite]] it was raining, the [[outdoor]] concert [[went]] [[ahead]].', ARRAY[]::text[], 0::int, ARRAY[]::text[], 'Sau là mệnh đề → Although.', 'mistakes', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'lien-tu-trang-tu-lien-ket'), 'choice', 'intermediate', 'The product is popular; ___, its price will increase next month.', ARRAY['although', 'however', 'despite', 'because']::text[], 1::int, ARRAY[]::text[], 'Trạng từ liên kết sau dấu chấm phẩy, nghĩa tương phản nhẹ → however.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'lien-tu-trang-tu-lien-ket'), 'choice', 'intermediate', 'We will begin the meeting ___ everyone has arrived.', ARRAY['once', 'despite', 'during', 'due to']::text[], 0::int, ARRAY[]::text[], 'Liên từ thời gian + mệnh đề → once.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'lien-tu-trang-tu-lien-ket'), 'choice', 'intermediate', '___ the high cost, many customers chose the premium plan.', ARRAY['Although', 'Despite', 'Because', 'Unless']::text[], 1::int, ARRAY[]::text[], 'Cụm danh từ, tương phản → Despite.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'lien-tu-trang-tu-lien-ket'), 'choice', 'intermediate', 'Please save your work regularly; ___, you may lose data.', ARRAY['therefore', 'otherwise', 'moreover', 'meanwhile']::text[], 1::int, ARRAY[]::text[], '"nếu không thì" → otherwise.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'lien-tu-trang-tu-lien-ket'), 'fill', 'intermediate', 'The applicant has ___ only experience but also strong references.', ARRAY[]::text[], NULL::int, ARRAY['not']::text[], '"not only … but also".', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'lien-tu-trang-tu-lien-ket'), 'fill', 'intermediate', 'Sales increased ___ the new advertising campaign. (because/because of)', ARRAY[]::text[], NULL::int, ARRAY['because of']::text[], 'Cụm danh từ → because of.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'lien-tu-trang-tu-lien-ket'), 'error', 'intermediate', 'The [[event]] was [[successful]]; [[although]], attendance was [[lower]] than expected.', ARRAY[]::text[], 2::int, ARRAY[]::text[], 'Nối hai câu sau dấu chấm phẩy → however.', 'mistakes', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'lien-tu-trang-tu-lien-ket'), 'error', 'intermediate', '[[Neither]] the CEO [[or]] the CFO [[was]] [[available]].', ARRAY[]::text[], 1::int, ARRAY[]::text[], '"neither … nor".', 'mistakes', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'lien-tu-trang-tu-lien-ket'), 'choice', 'advanced', 'The budget was approved, ___ several board members had expressed concerns.', ARRAY['despite', 'even though', 'in spite of', 'nevertheless']::text[], 1::int, ARRAY[]::text[], 'Mệnh đề phía sau, tương phản → even though.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'lien-tu-trang-tu-lien-ket'), 'choice', 'advanced', 'The supplier offered a discount ___ we placed the order before June.', ARRAY['provided that', 'in case of', 'in order', 'as a result']::text[], 0::int, ARRAY[]::text[], 'Điều kiện + mệnh đề → provided that.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'lien-tu-trang-tu-lien-ket'), 'choice', 'advanced', 'Demand has fallen sharply. ___, the factory will reduce production.', ARRAY['Consequently', 'Whereas', 'Unless', 'Although']::text[], 0::int, ARRAY[]::text[], 'Kết quả, đầu câu → Consequently.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'lien-tu-trang-tu-lien-ket'), 'fill', 'advanced', 'Profits rose this year, ___ revenue remained flat. (whereas/despite)', ARRAY[]::text[], NULL::int, ARRAY['whereas']::text[], 'Đối lập hai mệnh đề → whereas.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'lien-tu-trang-tu-lien-ket'), 'error', 'advanced', '[[In spite of]] the team [[worked]] overtime, the project [[was]] [[delayed]].', ARRAY[]::text[], 0::int, ARRAY[]::text[], 'Sau là mệnh đề → Although/Even though.', 'mistakes', now())
INSERT INTO "grammar_topics" ("slug", "name", "group_name", "level", "sort_order", "summary", "lesson", "toeic_categories", "roadmap_labels", "updated_at") VALUES ('menh-de-quan-he', 'Mệnh đề quan hệ và rút gọn', 'Mệnh đề', 'intermediate', 130, 'who, whom, whose, which, that, where và cách rút gọn mệnh đề quan hệ bằng V-ing / V3.', '{"when_to_use":"Khi chỗ trống đứng ngay sau một danh từ và trước một mệnh đề bổ nghĩa cho danh từ đó, hoặc khi lựa chọn có who/which/whose/that hoặc V-ing/V3 đứng sau danh từ.","structure":"• who: thay cho người, làm chủ ngữ (The man who called…).\n• whom: thay cho người, làm tân ngữ (The client whom we met…), đứng sau giới từ (to whom).\n• which: thay cho vật; có thể đứng sau dấu phẩy và sau giới từ (in which).\n• that: thay người/vật trong mệnh đề xác định; KHÔNG dùng sau dấu phẩy hay giới từ.\n• whose + danh từ: sở hữu (the company whose profits rose).\n• where = in/at which (nơi chốn); when = in/on which (thời gian).\nRút gọn: chủ động → V-ing (employees working late = who work late); bị động → V3 (the report submitted yesterday = which was submitted).","examples":[{"en":"The candidate who interviewed today was impressive.","vi":"Ứng viên phỏng vấn hôm nay rất ấn tượng."},{"en":"The firm, whose headquarters are in Seoul, is expanding.","vi":"Công ty có trụ sở ở Seoul đang mở rộng."},{"en":"The documents attached to this e-mail are confidential.","vi":"Tài liệu đính kèm thư này là mật. (rút gọn bị động)"},{"en":"Visitors wishing to park must register.","vi":"Khách muốn đỗ xe phải đăng ký. (rút gọn chủ động)"}],"mistakes":[{"wrong":"The manager which hired me has left.","right":"The manager who hired me has left.","note":"Người → who."},{"wrong":"The report, that I sent, is long.","right":"The report, which I sent, is long.","note":"Sau dấu phẩy không dùng that."},{"wrong":"The client who''s order was late called.","right":"The client whose order was late called.","note":"Sở hữu → whose."}],"signals":["Sau chỗ trống là danh từ không có mạo từ → whose.","Sau chỗ trống là động từ → who/which/that (chủ ngữ).","Sau chỗ trống là S + V và thiếu tân ngữ → whom/which/that.","Danh từ + ___ + by/tân ngữ: có \"by\" → V3; có tân ngữ → V-ing."]}'::jsonb, ARRAY['pronoun', 'prep_conj']::text[], ARRAY['Mệnh đề quan hệ và rút gọn mệnh đề quan hệ']::text[], now()) ON CONFLICT ("slug") DO NOTHING;
INSERT INTO "grammar_formulas" ("topic_id", "sort_order", "pattern", "usage", "examples", "updated_at") SELECT * FROM (VALUES
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'menh-de-quan-he'), 0, 'N(người) + who + V  |  N(người) + whom + S + V', 'who làm chủ ngữ, whom làm tân ngữ.', '[{"en":"the engineer who designed it","vi":""}]'::jsonb, now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'menh-de-quan-he'), 1, 'N + whose + N + V', 'Sở hữu.', '[{"en":"a supplier whose prices are low","vi":"nhà cung cấp có giá thấp"}]'::jsonb, now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'menh-de-quan-he'), 2, 'N + V-ing … (chủ động) | N + V3 … (bị động)', 'Rút gọn mệnh đề quan hệ.', '[{"en":"orders placed online","vi":"đơn đặt trực tuyến"}]'::jsonb, now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'menh-de-quan-he'), 3, 'N(nơi chốn) + where + S + V = in/at which', 'Mệnh đề quan hệ chỉ nơi chốn.', '[{"en":"the hotel where we stayed","vi":""}]'::jsonb, now())
INSERT INTO "grammar_exercises" ("topic_id", "kind", "level", "prompt", "options", "answer_index", "accepted_answers", "explanation", "lesson_section", "updated_at") SELECT * FROM (VALUES
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'menh-de-quan-he'), 'choice', 'basic', 'The woman ___ is speaking now is our new director.', ARRAY['which', 'who', 'whose', 'whom']::text[], 1::int, ARRAY[]::text[], 'Người, làm chủ ngữ → who.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'menh-de-quan-he'), 'choice', 'basic', 'The laptop ___ I bought last week is very fast.', ARRAY['who', 'which', 'whose', 'where']::text[], 1::int, ARRAY[]::text[], 'Vật, làm tân ngữ → which (hoặc that).', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'menh-de-quan-he'), 'choice', 'basic', 'This is the office ___ I work.', ARRAY['which', 'who', 'where', 'whose']::text[], 2::int, ARRAY[]::text[], 'Nơi chốn + mệnh đề đủ → where.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'menh-de-quan-he'), 'choice', 'basic', 'We hired a designer ___ work is well known.', ARRAY['who', 'whom', 'whose', 'which']::text[], 2::int, ARRAY[]::text[], 'Sở hữu + danh từ "work" → whose.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'menh-de-quan-he'), 'fill', 'basic', 'The customers ___ complained received a voucher. (who/which)', ARRAY[]::text[], NULL::int, ARRAY['who']::text[], 'Người → who.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'menh-de-quan-he'), 'fill', 'basic', 'The book ___ you recommended was helpful. (which/who)', ARRAY[]::text[], NULL::int, ARRAY['which', 'that']::text[], 'Vật → which/that.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'menh-de-quan-he'), 'error', 'basic', 'The [[engineer]] [[which]] fixed the [[printer]] has [[left]].', ARRAY[]::text[], 1::int, ARRAY[]::text[], 'Người → who.', 'mistakes', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'menh-de-quan-he'), 'choice', 'intermediate', 'The company, ___ was founded in 1990, employs 500 people.', ARRAY['that', 'which', 'who', 'what']::text[], 1::int, ARRAY[]::text[], 'Sau dấu phẩy, vật → which.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'menh-de-quan-he'), 'choice', 'intermediate', 'Employees ___ to attend the workshop should sign up today.', ARRAY['wish', 'wishing', 'wished', 'who wishing']::text[], 1::int, ARRAY[]::text[], 'Rút gọn chủ động (who wish) → wishing.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'menh-de-quan-he'), 'choice', 'intermediate', 'The products ___ last month have all been sold.', ARRAY['deliver', 'delivering', 'delivered', 'which delivered']::text[], 2::int, ARRAY[]::text[], 'Rút gọn bị động (which were delivered) → delivered.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'menh-de-quan-he'), 'choice', 'intermediate', 'Mr. Ross is the person to ___ you should send the invoice.', ARRAY['who', 'whom', 'which', 'that']::text[], 1::int, ARRAY[]::text[], 'Sau giới từ, người → whom.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'menh-de-quan-he'), 'fill', 'intermediate', 'The manager ___ (whose/who) team won the award gave a speech.', ARRAY[]::text[], NULL::int, ARRAY['whose']::text[], '"whose team" — sở hữu.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'menh-de-quan-he'), 'fill', 'intermediate', 'All forms ___ (submit) after the deadline will be rejected.', ARRAY[]::text[], NULL::int, ARRAY['submitted']::text[], 'Rút gọn bị động → submitted.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'menh-de-quan-he'), 'error', 'intermediate', 'The [[report]], [[that]] was [[released]] yesterday, shows [[strong]] growth.', ARRAY[]::text[], 1::int, ARRAY[]::text[], 'Sau dấu phẩy → which.', 'mistakes', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'menh-de-quan-he'), 'error', 'intermediate', 'Passengers [[travel]] with [[small]] children may board [[first]] [[today]].', ARRAY[]::text[], 0::int, ARRAY[]::text[], 'Rút gọn chủ động → traveling.', 'mistakes', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'menh-de-quan-he'), 'choice', 'advanced', 'The conference room, ___ seats 200 people, is available on Friday.', ARRAY['where', 'which', 'what', 'whose']::text[], 1::int, ARRAY[]::text[], 'Thiếu chủ ngữ cho "seats" → which (không phải where).', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'menh-de-quan-he'), 'choice', 'advanced', 'The applicants, most of ___ had prior experience, were interviewed.', ARRAY['who', 'whom', 'which', 'them']::text[], 1::int, ARRAY[]::text[], '"most of whom" — sau giới từ, người.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'menh-de-quan-he'), 'choice', 'advanced', 'The deadline ___ by the client cannot be changed.', ARRAY['set', 'setting', 'sets', 'which setting']::text[], 0::int, ARRAY[]::text[], 'Rút gọn bị động; "set" có V3 = set.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'menh-de-quan-he'), 'fill', 'advanced', 'The city ___ (where/which) we visited last year has a famous harbor.', ARRAY[]::text[], NULL::int, ARRAY['which', 'that']::text[], 'Thiếu tân ngữ cho "visited" → which/that.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'menh-de-quan-he'), 'error', 'advanced', 'The [[proposal]] [[submitting]] by the marketing team [[was]] [[approved]] yesterday.', ARRAY[]::text[], 1::int, ARRAY[]::text[], 'Đề xuất "được" nộp bởi nhóm marketing → rút gọn bị động: submitted.', 'mistakes', now())
INSERT INTO "grammar_topics" ("slug", "name", "group_name", "level", "sort_order", "summary", "lesson", "toeic_categories", "roadmap_labels", "updated_at") VALUES ('cau-dieu-kien', 'Câu điều kiện loại 1, 2, 3', 'Mệnh đề', 'intermediate', 140, 'If + hiện tại/quá khứ/quá khứ hoàn thành, unless, provided that và đảo ngữ Should/Were/Had.', '{"when_to_use":"Khi câu có if / unless / provided that / should ở đầu câu, và chỗ trống là động từ ở một trong hai mệnh đề.","structure":"• Loại 1 (có thể xảy ra): If + S + V(hiện tại), S + will/can + V.\n• Loại 2 (không có thật ở hiện tại): If + S + V2 (were cho mọi ngôi), S + would/could + V.\n• Loại 3 (không có thật ở quá khứ): If + S + had + V3, S + would/could have + V3.\n• Unless = if … not. Provided (that) / as long as = miễn là.\n• Đảo ngữ (bỏ if): Should + S + V (loại 1), Were + S + to V / Were + S (loại 2), Had + S + V3 (loại 3).","examples":[{"en":"If you register early, you will receive a discount.","vi":"Đăng ký sớm sẽ được giảm giá."},{"en":"If I were the manager, I would hire more staff.","vi":"Nếu tôi là quản lý, tôi sẽ tuyển thêm người."},{"en":"If we had known, we would have called.","vi":"Nếu biết, chúng tôi đã gọi."},{"en":"Should you have any questions, please contact us.","vi":"Nếu có câu hỏi, vui lòng liên hệ."}],"mistakes":[{"wrong":"If it will rain, we will cancel.","right":"If it rains, we will cancel.","note":"Mệnh đề if loại 1 dùng hiện tại."},{"wrong":"If I was you, I would accept.","right":"If I were you, I would accept.","note":"Loại 2 dùng were."},{"wrong":"If they had left earlier, they would catch the train.","right":"If they had left earlier, they would have caught the train.","note":"Loại 3: would have + V3."}],"signals":["Mệnh đề chính có will → mệnh đề if hiện tại đơn.","Mệnh đề chính có would + V → if + V2/were.","Mệnh đề chính có would have + V3 → if + had + V3.","Câu mở đầu bằng Should/Had/Were không có if → đảo ngữ điều kiện."]}'::jsonb, ARRAY['verb_tense']::text[], ARRAY['Câu điều kiện loại 1, 2, 3']::text[], now()) ON CONFLICT ("slug") DO NOTHING;
INSERT INTO "grammar_formulas" ("topic_id", "sort_order", "pattern", "usage", "examples", "updated_at") SELECT * FROM (VALUES
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cau-dieu-kien'), 0, 'If + S + V(hiện tại), S + will + V', 'Loại 1.', '[{"en":"If sales rise, we will hire.","vi":""}]'::jsonb, now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cau-dieu-kien'), 1, 'If + S + V2/were, S + would + V', 'Loại 2.', '[{"en":"If we had more time, we would expand.","vi":""}]'::jsonb, now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cau-dieu-kien'), 2, 'If + S + had V3, S + would have V3', 'Loại 3.', '[{"en":"If the order had arrived, we would have shipped it.","vi":""}]'::jsonb, now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cau-dieu-kien'), 3, 'Should + S + V … | Had + S + V3 …', 'Đảo ngữ điều kiện (trang trọng).', '[{"en":"Should you need help, call us.","vi":""}]'::jsonb, now())
INSERT INTO "grammar_exercises" ("topic_id", "kind", "level", "prompt", "options", "answer_index", "accepted_answers", "explanation", "lesson_section", "updated_at") SELECT * FROM (VALUES
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cau-dieu-kien'), 'choice', 'basic', 'If you ___ before 5 p.m., we will deliver today.', ARRAY['order', 'will order', 'ordered', 'had ordered']::text[], 0::int, ARRAY[]::text[], 'Loại 1 → hiện tại đơn.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cau-dieu-kien'), 'choice', 'basic', 'If it rains tomorrow, the picnic ___ canceled.', ARRAY['is', 'will be', 'would be', 'was']::text[], 1::int, ARRAY[]::text[], 'Loại 1 → will be.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cau-dieu-kien'), 'choice', 'basic', 'If I ___ more money, I would buy a new car.', ARRAY['have', 'had', 'will have', 'would have']::text[], 1::int, ARRAY[]::text[], 'Loại 2 → had.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cau-dieu-kien'), 'choice', 'basic', 'You will not get a refund ___ you keep the receipt.', ARRAY['if', 'unless', 'because', 'so']::text[], 1::int, ARRAY[]::text[], '"unless" = nếu không.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cau-dieu-kien'), 'fill', 'basic', 'If the weather ___ (be) nice, we will eat outside.', ARRAY[]::text[], NULL::int, ARRAY['is']::text[], 'Loại 1 → is.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cau-dieu-kien'), 'fill', 'basic', 'If I ___ (be) you, I would accept the offer.', ARRAY[]::text[], NULL::int, ARRAY['were']::text[], 'Loại 2 → were.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cau-dieu-kien'), 'error', 'basic', 'If you [[will need]] [[any]] help, please [[call]] [[me]].', ARRAY[]::text[], 0::int, ARRAY[]::text[], 'Mệnh đề if loại 1 → need.', 'mistakes', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cau-dieu-kien'), 'choice', 'intermediate', 'If the shipment had arrived on time, we ___ the deadline.', ARRAY['will meet', 'would meet', 'would have met', 'met']::text[], 2::int, ARRAY[]::text[], 'Loại 3 → would have met.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cau-dieu-kien'), 'choice', 'intermediate', '___ you have any questions, please contact customer service.', ARRAY['Should', 'Would', 'Had', 'Were']::text[], 0::int, ARRAY[]::text[], 'Đảo ngữ loại 1 → Should.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cau-dieu-kien'), 'choice', 'intermediate', 'The project would be finished by now if we ___ more staff.', ARRAY['have', 'had', 'will have', 'have had']::text[], 1::int, ARRAY[]::text[], 'Loại 2 → had.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cau-dieu-kien'), 'choice', 'intermediate', 'You may borrow the projector ___ you return it by Friday.', ARRAY['provided that', 'unless', 'despite', 'even if not']::text[], 0::int, ARRAY[]::text[], '"provided that" = miễn là.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cau-dieu-kien'), 'fill', 'intermediate', 'If we ___ (know) about the delay, we would have rescheduled.', ARRAY[]::text[], NULL::int, ARRAY['had known']::text[], 'Loại 3 → had known.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cau-dieu-kien'), 'fill', 'intermediate', 'The store would attract more customers if it ___ (open) on Sundays.', ARRAY[]::text[], NULL::int, ARRAY['opened']::text[], 'Loại 2 → opened.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cau-dieu-kien'), 'error', 'intermediate', 'If the [[manager]] [[had approved]] the plan, we [[would start]] [[last]] month.', ARRAY[]::text[], 2::int, ARRAY[]::text[], 'Loại 3 → would have started.', 'mistakes', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cau-dieu-kien'), 'error', 'intermediate', '[[Unless]] the [[price]] [[does not]] drop, we will [[cancel]] the order.', ARRAY[]::text[], 2::int, ARRAY[]::text[], '"Unless" đã mang nghĩa phủ định → Unless the price drops.', 'mistakes', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cau-dieu-kien'), 'choice', 'advanced', '___ the contract been signed earlier, the project would have started in May.', ARRAY['If', 'Should', 'Had', 'Were']::text[], 2::int, ARRAY[]::text[], 'Đảo ngữ loại 3 → Had.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cau-dieu-kien'), 'choice', 'advanced', 'Were the company ___ its prices, it would lose customers.', ARRAY['raise', 'to raise', 'raising', 'raised']::text[], 1::int, ARRAY[]::text[], 'Đảo ngữ loại 2: Were + S + to V.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cau-dieu-kien'), 'choice', 'advanced', 'If the company ___ more engineers, it could finish the project sooner.', ARRAY['hires', 'hired', 'had hired', 'will hire']::text[], 1::int, ARRAY[]::text[], 'Mệnh đề chính "could + V" → loại 2: If + V2 (hired).', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cau-dieu-kien'), 'fill', 'advanced', 'Should the client ___ (request) changes, we will revise the design.', ARRAY[]::text[], NULL::int, ARRAY['request']::text[], 'Should + S + V nguyên mẫu.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'cau-dieu-kien'), 'error', 'advanced', '[[Had]] the team [[tested]] the software, they [[would detect]] the error [[before]] launch.', ARRAY[]::text[], 2::int, ARRAY[]::text[], 'Loại 3 → would have detected.', 'mistakes', now())
INSERT INTO "grammar_topics" ("slug", "name", "group_name", "level", "sort_order", "summary", "lesson", "toeic_categories", "roadmap_labels", "updated_at") VALUES ('menh-de-danh-tu-cau-gian-tiep', 'Mệnh đề danh từ, câu gián tiếp', 'Mệnh đề', 'advanced', 150, 'that / whether / what / how làm chủ ngữ hoặc tân ngữ; câu hỏi gián tiếp giữ trật tự S + V.', '{"when_to_use":"Khi một mệnh đề đóng vai danh từ: làm chủ ngữ (What he said is true), tân ngữ (I wonder whether …) hoặc sau giới từ (about how …). Lựa chọn thường là that / what / whether / which / if.","structure":"• that + mệnh đề ĐỦ thành phần: She said that the store was closed.\n• what + mệnh đề THIẾU (thiếu chủ ngữ hoặc tân ngữ): What we need is time.\n• whether (or not) / if: \"có … hay không\"; sau giới từ và ở đầu câu chỉ dùng whether.\n• who / where / when / how / why + S + V: câu hỏi gián tiếp, KHÔNG đảo trợ động từ (Do you know where the office is?).\n• Câu tường thuật lùi thì: said that … was / would / had V3.","examples":[{"en":"What the customers want is faster delivery.","vi":"Điều khách muốn là giao nhanh hơn."},{"en":"We are not sure whether the event will be postponed.","vi":"Chưa chắc sự kiện có hoãn hay không."},{"en":"Could you tell me where the meeting room is?","vi":"Cho tôi hỏi phòng họp ở đâu?"},{"en":"The manager announced that the office would close early.","vi":"Quản lý thông báo văn phòng sẽ đóng sớm."}],"mistakes":[{"wrong":"Do you know where is the station?","right":"Do you know where the station is?","note":"Câu hỏi gián tiếp không đảo ngữ."},{"wrong":"That he said was surprising.","right":"What he said was surprising.","note":"Mệnh đề thiếu tân ngữ → what."},{"wrong":"It depends on if the budget is approved.","right":"It depends on whether the budget is approved.","note":"Sau giới từ dùng whether."}],"signals":["Mệnh đề sau chỗ trống đã đủ S + V + O → that.","Mệnh đề sau chỗ trống thiếu S hoặc O → what.","Có \"or not\" hoặc nghĩa \"có … hay không\" → whether.","Sau giới từ → whether / what / how (không dùng that, if)."]}'::jsonb, ARRAY['prep_conj']::text[], ARRAY['Mệnh đề danh từ, câu gián tiếp']::text[], now()) ON CONFLICT ("slug") DO NOTHING;
INSERT INTO "grammar_formulas" ("topic_id", "sort_order", "pattern", "usage", "examples", "updated_at") SELECT * FROM (VALUES
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'menh-de-danh-tu-cau-gian-tiep'), 0, 'that + S + V (đủ)', 'Mệnh đề danh từ đầy đủ.', '[{"en":"It is clear that prices will rise.","vi":""}]'::jsonb, now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'menh-de-danh-tu-cau-gian-tiep'), 1, 'what + (S) + V (thiếu)', 'what = the thing(s) that.', '[{"en":"This is what we ordered.","vi":""}]'::jsonb, now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'menh-de-danh-tu-cau-gian-tiep'), 2, 'whether + S + V (or not)', '"có … hay không"; dùng được sau giới từ.', '[{"en":"regardless of whether you attend","vi":""}]'::jsonb, now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'menh-de-danh-tu-cau-gian-tiep'), 3, 'wh-word + S + V (không đảo)', 'Câu hỏi gián tiếp.', '[{"en":"I wonder when the store opens.","vi":""}]'::jsonb, now())
INSERT INTO "grammar_exercises" ("topic_id", "kind", "level", "prompt", "options", "answer_index", "accepted_answers", "explanation", "lesson_section", "updated_at") SELECT * FROM (VALUES
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'menh-de-danh-tu-cau-gian-tiep'), 'choice', 'basic', 'Please tell me ___ the meeting starts.', ARRAY['when', 'what', 'that', 'which']::text[], 0::int, ARRAY[]::text[], 'Hỏi thời gian, mệnh đề đủ → when.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'menh-de-danh-tu-cau-gian-tiep'), 'choice', 'basic', 'I don''t know ___ he will come or not.', ARRAY['that', 'what', 'whether', 'which']::text[], 2::int, ARRAY[]::text[], '"or not" → whether.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'menh-de-danh-tu-cau-gian-tiep'), 'choice', 'basic', 'She said ___ she would be late.', ARRAY['what', 'that', 'whether', 'who']::text[], 1::int, ARRAY[]::text[], 'Mệnh đề đủ → that.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'menh-de-danh-tu-cau-gian-tiep'), 'fill', 'basic', 'Do you know where the station ___? (is)', ARRAY[]::text[], NULL::int, ARRAY['is']::text[], 'Câu hỏi gián tiếp: where + S + V.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'menh-de-danh-tu-cau-gian-tiep'), 'choice', 'intermediate', '___ the company needs most is experienced staff.', ARRAY['That', 'What', 'Which', 'Whether']::text[], 1::int, ARRAY[]::text[], 'Mệnh đề thiếu tân ngữ của "needs" → What.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'menh-de-danh-tu-cau-gian-tiep'), 'choice', 'intermediate', 'The success of the plan depends on ___ we can secure funding.', ARRAY['that', 'if', 'whether', 'what']::text[], 2::int, ARRAY[]::text[], 'Sau giới từ "on" → whether.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'menh-de-danh-tu-cau-gian-tiep'), 'choice', 'intermediate', 'Could you tell me how much ___?', ARRAY['does the ticket cost', 'the ticket costs', 'costs the ticket', 'the ticket does cost']::text[], 1::int, ARRAY[]::text[], 'Câu hỏi gián tiếp không đảo: the ticket costs.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'menh-de-danh-tu-cau-gian-tiep'), 'choice', 'intermediate', 'It is essential ___ all staff complete the survey.', ARRAY['what', 'that', 'whether', 'which']::text[], 1::int, ARRAY[]::text[], 'Mệnh đề đủ → that.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'menh-de-danh-tu-cau-gian-tiep'), 'fill', 'intermediate', 'The director explained ___ the project had been delayed. (why/what)', ARRAY[]::text[], NULL::int, ARRAY['why']::text[], 'Mệnh đề đủ, giải thích lý do → why.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'menh-de-danh-tu-cau-gian-tiep'), 'fill', 'intermediate', 'We have not decided ___ to renew the contract. (whether/that)', ARRAY[]::text[], NULL::int, ARRAY['whether']::text[], '"whether + to V".', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'menh-de-danh-tu-cau-gian-tiep'), 'error', 'intermediate', 'Can you [[tell]] me [[where]] [[is]] the [[conference room]]?', ARRAY[]::text[], 2::int, ARRAY[]::text[], 'Câu hỏi gián tiếp: where the conference room is.', 'mistakes', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'menh-de-danh-tu-cau-gian-tiep'), 'error', 'intermediate', '[[That]] the [[client]] requested [[was]] not [[possible]].', ARRAY[]::text[], 0::int, ARRAY[]::text[], 'Mệnh đề thiếu tân ngữ → What.', 'mistakes', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'menh-de-danh-tu-cau-gian-tiep'), 'choice', 'advanced', 'The manager questioned ___ the figures in the report were accurate.', ARRAY['what', 'whether', 'that', 'which']::text[], 1::int, ARRAY[]::text[], '"questioned whether" = nghi ngờ liệu.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'menh-de-danh-tu-cau-gian-tiep'), 'choice', 'advanced', '___ the merger will be approved remains uncertain.', ARRAY['If', 'What', 'Whether', 'That']::text[], 2::int, ARRAY[]::text[], 'Đầu câu, nghĩa "có hay không" → Whether (không dùng If).', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'menh-de-danh-tu-cau-gian-tiep'), 'choice', 'advanced', 'The CEO announced that the company ___ two new factories the following year.', ARRAY['opens', 'will open', 'would open', 'has opened']::text[], 2::int, ARRAY[]::text[], 'Tường thuật lùi thì: will → would.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'menh-de-danh-tu-cau-gian-tiep'), 'choice', 'advanced', 'We were impressed by ___ quickly the team adapted to the new system.', ARRAY['what', 'how', 'that', 'whether']::text[], 1::int, ARRAY[]::text[], '"how + adv" = mức độ.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'menh-de-danh-tu-cau-gian-tiep'), 'fill', 'advanced', '___ (whoever/whomever) submits the best proposal will win the contract.', ARRAY[]::text[], NULL::int, ARRAY['Whoever']::text[], 'Làm chủ ngữ của "submits" → Whoever.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'menh-de-danh-tu-cau-gian-tiep'), 'fill', 'advanced', 'The client asked whether the price ___ (include) delivery.', ARRAY[]::text[], NULL::int, ARRAY['included', 'includes']::text[], 'Tường thuật (lùi thì) → included.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'menh-de-danh-tu-cau-gian-tiep'), 'error', 'advanced', 'The [[committee]] has not [[yet]] decided [[that]] the event [[will be]] held indoors.', ARRAY[]::text[], 2::int, ARRAY[]::text[], '"chưa quyết định liệu" → whether.', 'mistakes', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'menh-de-danh-tu-cau-gian-tiep'), 'error', 'advanced', 'Please [[let]] us know [[if]] or not you [[will attend]] the [[dinner]].', ARRAY[]::text[], 1::int, ARRAY[]::text[], '"or not" ngay sau → whether.', 'mistakes', now())
INSERT INTO "grammar_topics" ("slug", "name", "group_name", "level", "sort_order", "summary", "lesson", "toeic_categories", "roadmap_labels", "updated_at") VALUES ('dao-ngu-cau-nhan-manh', 'Đảo ngữ và câu nhấn mạnh', 'Cấu trúc đặc biệt', 'advanced', 160, 'Đảo ngữ với Not only, Never, Rarely, Only after, Hardly … when; câu chẻ It is … that.', '{"when_to_use":"Khi câu mở đầu bằng trạng từ phủ định hoặc hạn chế (Never, Rarely, Seldom, Not only, Only + …, No sooner, Hardly) — phần sau phải đảo trợ động từ lên trước chủ ngữ. Câu chẻ dùng để nhấn mạnh một thành phần.","structure":"• Never / Rarely / Seldom / Little + trợ động từ + S + V: Rarely does the CEO attend.\n• Not only + trợ động từ + S + V, but S + also V.\n• Only after / Only when / Only if + mệnh đề + trợ động từ + S + V.\n• No sooner had + S + V3 + than …; Hardly/Scarcely had + S + V3 + when …\n• Not until + mốc/mệnh đề + trợ động từ + S + V.\n• Câu chẻ: It is/was + thành phần nhấn mạnh + that/who + phần còn lại.","examples":[{"en":"Never have we seen such strong sales.","vi":"Chưa bao giờ doanh số mạnh như vậy."},{"en":"Not only did the firm cut costs, but it also raised wages.","vi":"Công ty không chỉ cắt giảm chi phí mà còn tăng lương."},{"en":"Only after the audit was the error discovered.","vi":"Mãi sau kiểm toán lỗi mới được phát hiện."},{"en":"It was Ms. Kim who suggested the idea.","vi":"Chính bà Kim là người đề xuất ý tưởng."}],"mistakes":[{"wrong":"Rarely the manager works late.","right":"Rarely does the manager work late.","note":"Sau Rarely đảo trợ động từ."},{"wrong":"Not only he speaks French, but also German.","right":"Not only does he speak French, but he also speaks German.","note":"Đảo ngữ sau Not only."},{"wrong":"No sooner had we arrived when it rained.","right":"No sooner had we arrived than it rained.","note":"No sooner … than."}],"signals":["Câu bắt đầu bằng Never/Rarely/Seldom/Hardly/Not only/Only + … → tìm lựa chọn có trợ động từ đứng trước chủ ngữ.","No sooner → than; Hardly/Scarcely → when.","It is/was … ___ → that / who."]}'::jsonb, ARRAY[]::text[], ARRAY['Đảo ngữ và câu nhấn mạnh']::text[], now()) ON CONFLICT ("slug") DO NOTHING;
INSERT INTO "grammar_formulas" ("topic_id", "sort_order", "pattern", "usage", "examples", "updated_at") SELECT * FROM (VALUES
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'dao-ngu-cau-nhan-manh'), 0, 'Never/Rarely/Seldom + aux + S + V', 'Đảo ngữ với trạng từ phủ định.', '[{"en":"Seldom do we receive complaints.","vi":""}]'::jsonb, now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'dao-ngu-cau-nhan-manh'), 1, 'Not only + aux + S + V, but (S) also V', 'Đảo ngữ Not only.', '[{"en":"Not only is it cheap, but it is also durable.","vi":""}]'::jsonb, now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'dao-ngu-cau-nhan-manh'), 2, 'No sooner had S V3 than … | Hardly had S V3 when …', 'Vừa mới … thì …', '[{"en":"Hardly had she left when the phone rang.","vi":""}]'::jsonb, now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'dao-ngu-cau-nhan-manh'), 3, 'It is/was + X + that/who …', 'Câu chẻ nhấn mạnh.', '[{"en":"It was in 2010 that the firm was founded.","vi":""}]'::jsonb, now())
INSERT INTO "grammar_exercises" ("topic_id", "kind", "level", "prompt", "options", "answer_index", "accepted_answers", "explanation", "lesson_section", "updated_at") SELECT * FROM (VALUES
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'dao-ngu-cau-nhan-manh'), 'choice', 'intermediate', 'Rarely ___ the director miss a meeting.', ARRAY['does', 'do', 'is', 'has']::text[], 0::int, ARRAY[]::text[], 'Đảo ngữ sau Rarely, chủ ngữ số ít, hiện tại → does.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'dao-ngu-cau-nhan-manh'), 'choice', 'intermediate', 'Never ___ such a large order before.', ARRAY['we received', 'have we received', 'we have received', 'received we']::text[], 1::int, ARRAY[]::text[], 'Đảo ngữ: Never + have + S + V3.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'dao-ngu-cau-nhan-manh'), 'choice', 'intermediate', 'It was Mr. Han ___ negotiated the deal.', ARRAY['which', 'who', 'whom', 'what']::text[], 1::int, ARRAY[]::text[], 'Câu chẻ nhấn mạnh người làm chủ ngữ → who (hoặc that).', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'dao-ngu-cau-nhan-manh'), 'choice', 'intermediate', 'Not only ___ the product cheap, but it is also durable.', ARRAY['is', 'it is', 'does', 'was it']::text[], 0::int, ARRAY[]::text[], 'Not only + is + S.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'dao-ngu-cau-nhan-manh'), 'fill', 'intermediate', 'No sooner had the meeting started ___ the power went out.', ARRAY[]::text[], NULL::int, ARRAY['than']::text[], 'No sooner … than.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'dao-ngu-cau-nhan-manh'), 'fill', 'intermediate', 'Hardly had we arrived ___ it started to rain.', ARRAY[]::text[], NULL::int, ARRAY['when', 'before']::text[], 'Hardly … when.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'dao-ngu-cau-nhan-manh'), 'error', 'intermediate', 'Seldom [[the]] [[company]] [[offers]] such large [[discounts]].', ARRAY[]::text[], 0::int, ARRAY[]::text[], 'Đảo ngữ: Seldom does the company offer…', 'mistakes', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'dao-ngu-cau-nhan-manh'), 'choice', 'advanced', 'Only after the contract was signed ___ the work begin.', ARRAY['did', 'does', 'had', 'was']::text[], 0::int, ARRAY[]::text[], 'Only after + mệnh đề + did + S + V.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'dao-ngu-cau-nhan-manh'), 'choice', 'advanced', 'Not until the end of the year ___ the final results.', ARRAY['we will know', 'will we know', 'we know', 'know we']::text[], 1::int, ARRAY[]::text[], 'Not until … + will + S + V.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'dao-ngu-cau-nhan-manh'), 'choice', 'advanced', 'Under no circumstances ___ employees share their passwords.', ARRAY['should', 'they should', 'do they', 'must they']::text[], 0::int, ARRAY[]::text[], 'Under no circumstances + should + S + V.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'dao-ngu-cau-nhan-manh'), 'choice', 'advanced', 'Little ___ that the merger would fail.', ARRAY['they knew', 'did they know', 'they did know', 'knew they']::text[], 1::int, ARRAY[]::text[], 'Little + did + S + V.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'dao-ngu-cau-nhan-manh'), 'choice', 'advanced', 'So successful ___ that a second edition was printed.', ARRAY['the book was', 'was the book', 'did the book', 'the book did']::text[], 1::int, ARRAY[]::text[], 'So + adj + be + S + that.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'dao-ngu-cau-nhan-manh'), 'fill', 'advanced', 'Only when all the data is collected ___ (can) we draw conclusions.', ARRAY[]::text[], NULL::int, ARRAY['can']::text[], 'Only when … + can + S + V.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'dao-ngu-cau-nhan-manh'), 'fill', 'advanced', 'It is the quality, not the price, ___ attracts our customers.', ARRAY[]::text[], NULL::int, ARRAY['that', 'which']::text[], 'Câu chẻ nhấn mạnh vật → that.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'dao-ngu-cau-nhan-manh'), 'error', 'advanced', 'Not only [[did]] the store [[extend]] its hours, but it [[also]] [[hiring]] more staff.', ARRAY[]::text[], 3::int, ARRAY[]::text[], 'Song song: but it also hired.', 'mistakes', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'dao-ngu-cau-nhan-manh'), 'error', 'advanced', 'Only [[by]] working together [[we can]] [[meet]] the [[deadline]].', ARRAY[]::text[], 1::int, ARRAY[]::text[], 'Only + by … → can we meet.', 'mistakes', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'dao-ngu-cau-nhan-manh'), 'error', 'advanced', 'At no time [[the system]] [[was]] [[at risk]] of [[failure]].', ARRAY[]::text[], 0::int, ARRAY[]::text[], 'Đảo ngữ: At no time was the system at risk.', 'mistakes', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'dao-ngu-cau-nhan-manh'), 'choice', 'advanced', 'Scarcely ___ the presentation when questions began.', ARRAY['she had finished', 'had she finished', 'she finished', 'did she finished']::text[], 1::int, ARRAY[]::text[], 'Scarcely + had + S + V3.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'dao-ngu-cau-nhan-manh'), 'fill', 'advanced', 'Rarely ___ (have) the team missed a deadline.', ARRAY[]::text[], NULL::int, ARRAY['has']::text[], 'Rarely + has + S + V3.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'dao-ngu-cau-nhan-manh'), 'choice', 'advanced', 'It was not until 2019 ___ the company became profitable.', ARRAY['when', 'that', 'which', 'then']::text[], 1::int, ARRAY[]::text[], '"It was not until … that …".', 'structure', now())
INSERT INTO "grammar_topics" ("slug", "name", "group_name", "level", "sort_order", "summary", "lesson", "toeic_categories", "roadmap_labels", "updated_at") VALUES ('gia-dinh-cau-truc-trang-trong', 'Giả định và cấu trúc trang trọng', 'Cấu trúc đặc biệt', 'advanced', 170, 'recommend/require/suggest that + S + V nguyên mẫu; It is essential that …; would rather, It is time.', '{"when_to_use":"Khi câu có động từ hoặc tính từ chỉ yêu cầu, đề nghị, tầm quan trọng theo sau bởi \"that\". Mệnh đề \"that\" khi ấy dùng động từ NGUYÊN MẪU cho mọi ngôi (không -s, không chia thì).","structure":"• Động từ: recommend, suggest, request, require, insist, ask, propose, demand, advise + that + S + V(nguyên mẫu).\n• Tính từ: essential, important, necessary, vital, imperative, crucial + that + S + V(nguyên mẫu).\n• Danh từ: recommendation, request, requirement + that + S + V(nguyên mẫu).\n• Bị động: that + S + be + V3 (It is required that all forms be signed).\n• would rather + S + V2 (muốn ai làm gì ở hiện tại); It is (high) time + S + V2.","examples":[{"en":"The manager requested that every employee submit a report.","vi":"Quản lý yêu cầu mỗi nhân viên nộp báo cáo."},{"en":"It is essential that the data be backed up daily.","vi":"Cần thiết là dữ liệu phải được sao lưu mỗi ngày."},{"en":"We recommend that she attend the training.","vi":"Chúng tôi đề nghị cô ấy dự buổi đào tạo."},{"en":"It is time we updated the website.","vi":"Đã đến lúc cập nhật trang web."}],"mistakes":[{"wrong":"They suggested that he takes a break.","right":"They suggested that he take a break.","note":"Giả định → V nguyên mẫu."},{"wrong":"It is vital that the door is locked.","right":"It is vital that the door be locked.","note":"Bị động giả định → be + V3."},{"wrong":"The rule requires that all visitors will register.","right":"The rule requires that all visitors register.","note":"Không dùng will."}],"signals":["Thấy recommend/suggest/require/request/insist/ask + that → chọn V nguyên mẫu.","Thấy It is essential/important/necessary/imperative that → chọn V nguyên mẫu hoặc be + V3.","Chủ ngữ số ít mà lựa chọn có cả \"submit\" và \"submits\" → nghĩ tới giả định."]}'::jsonb, ARRAY['verb_tense']::text[], ARRAY['Giả định và các cấu trúc trang trọng']::text[], now()) ON CONFLICT ("slug") DO NOTHING;
INSERT INTO "grammar_formulas" ("topic_id", "sort_order", "pattern", "usage", "examples", "updated_at") SELECT * FROM (VALUES
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'gia-dinh-cau-truc-trang-trong'), 0, 'recommend/suggest/require/request + that + S + V(nguyên mẫu)', 'Giả định sau động từ.', '[{"en":"We suggest that he contact HR.","vi":""}]'::jsonb, now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'gia-dinh-cau-truc-trang-trong'), 1, 'It is essential/important/necessary + that + S + V(nguyên mẫu)', 'Giả định sau tính từ.', '[{"en":"It is important that she be on time.","vi":""}]'::jsonb, now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'gia-dinh-cau-truc-trang-trong'), 2, '… that + S + be + V3', 'Giả định bị động.', '[{"en":"We ask that all phones be turned off.","vi":""}]'::jsonb, now())
INSERT INTO "grammar_exercises" ("topic_id", "kind", "level", "prompt", "options", "answer_index", "accepted_answers", "explanation", "lesson_section", "updated_at") SELECT * FROM (VALUES
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'gia-dinh-cau-truc-trang-trong'), 'choice', 'intermediate', 'The doctor recommended that he ___ more exercise.', ARRAY['gets', 'get', 'got', 'will get']::text[], 1::int, ARRAY[]::text[], 'recommend that + V nguyên mẫu.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'gia-dinh-cau-truc-trang-trong'), 'choice', 'intermediate', 'It is important that every participant ___ the form.', ARRAY['sign', 'signs', 'signed', 'will sign']::text[], 0::int, ARRAY[]::text[], 'It is important that + V nguyên mẫu.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'gia-dinh-cau-truc-trang-trong'), 'choice', 'intermediate', 'The policy requires that all visitors ___ an ID.', ARRAY['shows', 'show', 'showed', 'showing']::text[], 1::int, ARRAY[]::text[], 'require that + V nguyên mẫu.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'gia-dinh-cau-truc-trang-trong'), 'choice', 'intermediate', 'We suggest that the meeting ___ until next week.', ARRAY['postpones', 'be postponed', 'is postponed', 'will postpone']::text[], 1::int, ARRAY[]::text[], 'Bị động giả định → be postponed.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'gia-dinh-cau-truc-trang-trong'), 'fill', 'intermediate', 'The manager insisted that Ms. Ito ___ (attend) the conference.', ARRAY[]::text[], NULL::int, ARRAY['attend']::text[], 'insist that + V nguyên mẫu.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'gia-dinh-cau-truc-trang-trong'), 'fill', 'intermediate', 'It is essential that the documents ___ (sign) before Friday.', ARRAY[]::text[], NULL::int, ARRAY['be signed']::text[], 'Bị động giả định → be signed.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'gia-dinh-cau-truc-trang-trong'), 'error', 'intermediate', 'The [[client]] requested that the [[order]] [[is delivered]] [[by]] Monday.', ARRAY[]::text[], 2::int, ARRAY[]::text[], 'Giả định bị động → be delivered.', 'mistakes', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'gia-dinh-cau-truc-trang-trong'), 'error', 'intermediate', 'It is [[necessary]] that each [[employee]] [[completes]] the [[training]].', ARRAY[]::text[], 2::int, ARRAY[]::text[], 'Giả định → complete.', 'mistakes', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'gia-dinh-cau-truc-trang-trong'), 'choice', 'advanced', 'The committee proposed that the budget ___ by ten percent.', ARRAY['increases', 'be increased', 'is increased', 'increasing']::text[], 1::int, ARRAY[]::text[], 'Ngân sách "được tăng" → be increased.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'gia-dinh-cau-truc-trang-trong'), 'choice', 'advanced', 'It is imperative that the safety rules ___ at all times.', ARRAY['are followed', 'be followed', 'follow', 'followed']::text[], 1::int, ARRAY[]::text[], 'Giả định bị động → be followed.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'gia-dinh-cau-truc-trang-trong'), 'choice', 'advanced', 'Our recommendation is that the firm ___ a new supplier.', ARRAY['seeks', 'seek', 'sought', 'seeking']::text[], 1::int, ARRAY[]::text[], 'Danh từ recommendation + that + V nguyên mẫu.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'gia-dinh-cau-truc-trang-trong'), 'choice', 'advanced', 'It is high time the company ___ its outdated software.', ARRAY['replace', 'replaces', 'replaced', 'will replace']::text[], 2::int, ARRAY[]::text[], '"It is high time + S + V2".', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'gia-dinh-cau-truc-trang-trong'), 'choice', 'advanced', 'I would rather you ___ the report by e-mail.', ARRAY['send', 'sent', 'sending', 'will send']::text[], 1::int, ARRAY[]::text[], '"would rather + S + V2" (hiện tại).', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'gia-dinh-cau-truc-trang-trong'), 'fill', 'advanced', 'The board demanded that the CEO ___ (explain) the losses.', ARRAY[]::text[], NULL::int, ARRAY['explain']::text[], 'demand that + V nguyên mẫu.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'gia-dinh-cau-truc-trang-trong'), 'fill', 'advanced', 'It is crucial that the client ___ (not / inform) until the deal is final.', ARRAY[]::text[], NULL::int, ARRAY['not be informed']::text[], 'Phủ định giả định bị động: not be + V3.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'gia-dinh-cau-truc-trang-trong'), 'error', 'advanced', 'The auditor [[advised]] that the company [[revises]] its [[accounting]] [[procedures]].', ARRAY[]::text[], 1::int, ARRAY[]::text[], 'Giả định → revise.', 'mistakes', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'gia-dinh-cau-truc-trang-trong'), 'error', 'advanced', 'It is [[vital]] that every [[shipment]] [[will be]] [[inspected]].', ARRAY[]::text[], 2::int, ARRAY[]::text[], 'Giả định bị động → be (bỏ will).', 'mistakes', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'gia-dinh-cau-truc-trang-trong'), 'choice', 'advanced', 'The landlord asked that the tenants ___ noise after 10 p.m.', ARRAY['avoid', 'avoids', 'avoided', 'are avoiding']::text[], 0::int, ARRAY[]::text[], 'ask that + V nguyên mẫu.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'gia-dinh-cau-truc-trang-trong'), 'fill', 'advanced', 'It is recommended that passengers ___ (arrive) two hours early.', ARRAY[]::text[], NULL::int, ARRAY['arrive']::text[], 'Giả định → arrive.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'gia-dinh-cau-truc-trang-trong'), 'choice', 'advanced', 'The requirement that each applicant ___ a portfolio was removed.', ARRAY['submit', 'submits', 'submitted', 'will submit']::text[], 0::int, ARRAY[]::text[], 'requirement that + V nguyên mẫu.', 'structure', now())
INSERT INTO "grammar_topics" ("slug", "name", "group_name", "level", "sort_order", "summary", "lesson", "toeic_categories", "roadmap_labels", "updated_at") VALUES ('tu-noi-chen-cau-part-6', 'Từ nối và chèn câu trong đoạn văn (Part 6)', 'Liên kết đoạn văn', 'advanced', 180, 'Chọn từ nối và câu chèn dựa vào ý câu trước – câu sau, đại từ và từ khóa lặp lại trong đoạn.', '{"when_to_use":"Part 6 có câu hỏi chọn từ nối (However, Therefore, In addition…) và câu hỏi chọn cả một câu điền vào chỗ trống. Không đọc riêng câu có chỗ trống: phải đọc câu ngay trước và ngay sau.","structure":"Quan hệ giữa hai câu → từ nối:\n• Bổ sung: In addition, Moreover, Furthermore, Also.\n• Tương phản: However, Nevertheless, On the other hand, Instead.\n• Kết quả: Therefore, As a result, Consequently, Accordingly.\n• Ví dụ: For example, For instance.\n• Thời gian/trình tự: First, Then, Afterward, Meanwhile, Finally.\nChèn câu: câu đúng phải (1) khớp chủ đề đoạn, (2) nối được với câu trước bằng đại từ (this, these, it, they) hoặc từ lặp lại, (3) dẫn được sang câu sau. Loại câu nói đến thông tin chưa từng xuất hiện hoặc mâu thuẫn với đoạn.","examples":[{"en":"The store will close early on Friday. In addition, it will be closed on Saturday.","vi":"Bổ sung thông tin."},{"en":"Sales fell in March. However, they recovered in April.","vi":"Tương phản."},{"en":"The road is under repair. Therefore, please use the north entrance.","vi":"Kết quả."},{"en":"We have received your application. It will be reviewed within two weeks.","vi":"\"It\" nối với \"your application\"."}],"mistakes":[{"wrong":"The price is low. Therefore, the quality is poor.","right":"The price is low. However, the quality is high.","note":"Chọn từ nối theo quan hệ ý, không theo cảm tính."},{"wrong":"Chọn câu chèn có từ \"these changes\" khi câu trước chưa nói đến thay đổi nào.","right":"Chọn câu mà \"these …\" trỏ về đúng thứ đã nhắc ở câu trước.","note":"Đại từ phải có chỗ trỏ về."}],"signals":["Câu sau trái ý câu trước → However / Nevertheless.","Câu sau là hệ quả → Therefore / As a result.","Câu sau thêm ý cùng chiều → In addition / Moreover.","Câu chèn có đại từ (this, they, such) → tìm danh từ nó thay thế ở câu ngay trước."]}'::jsonb, ARRAY['sentence_insertion']::text[], ARRAY['Từ nối và liên kết câu trong Part 6', 'Câu hỏi ngữ pháp bẫy về nghĩa trong Part 5–6']::text[], now()) ON CONFLICT ("slug") DO NOTHING;
INSERT INTO "grammar_formulas" ("topic_id", "sort_order", "pattern", "usage", "examples", "updated_at") SELECT * FROM (VALUES
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'tu-noi-chen-cau-part-6'), 0, 'Câu A. However/Nevertheless, câu B (trái ý).', 'Tương phản giữa hai câu.', '[{"en":"The office is small. However, it is well equipped.","vi":""}]'::jsonb, now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'tu-noi-chen-cau-part-6'), 1, 'Câu A. Therefore/As a result, câu B (hệ quả).', 'Kết quả.', '[{"en":"The flight was canceled. As a result, the meeting moved online.","vi":""}]'::jsonb, now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'tu-noi-chen-cau-part-6'), 2, 'Câu A. In addition/Moreover, câu B (thêm ý).', 'Bổ sung.', '[{"en":"The plan is cheaper. Moreover, it is faster.","vi":""}]'::jsonb, now())
INSERT INTO "grammar_exercises" ("topic_id", "kind", "level", "prompt", "options", "answer_index", "accepted_answers", "explanation", "lesson_section", "updated_at") SELECT * FROM (VALUES
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'tu-noi-chen-cau-part-6'), 'choice', 'intermediate', 'The hotel offers free Wi-Fi. ___, guests can use the fitness center at no charge.', ARRAY['However', 'In addition', 'Therefore', 'Instead']::text[], 1::int, ARRAY[]::text[], 'Thêm ý cùng chiều → In addition.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'tu-noi-chen-cau-part-6'), 'choice', 'intermediate', 'Our main road is closed for repairs. ___, please use the side entrance.', ARRAY['Therefore', 'However', 'For example', 'Moreover']::text[], 0::int, ARRAY[]::text[], 'Hệ quả → Therefore.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'tu-noi-chen-cau-part-6'), 'choice', 'intermediate', 'The new printer is fast. ___, it is expensive to maintain.', ARRAY['As a result', 'However', 'In addition', 'Similarly']::text[], 1::int, ARRAY[]::text[], 'Tương phản → However.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'tu-noi-chen-cau-part-6'), 'choice', 'intermediate', 'We offer many benefits. ___, employees receive free lunch every Friday.', ARRAY['For example', 'However', 'Otherwise', 'Instead']::text[], 0::int, ARRAY[]::text[], 'Đưa ví dụ → For example.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'tu-noi-chen-cau-part-6'), 'choice', 'intermediate', 'Please complete the form. ___, return it to the front desk.', ARRAY['However', 'Then', 'Instead', 'Otherwise']::text[], 1::int, ARRAY[]::text[], 'Trình tự → Then.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'tu-noi-chen-cau-part-6'), 'fill', 'intermediate', 'The event was postponed due to rain. ___, it will be held next Saturday. (Instead/However)', ARRAY[]::text[], NULL::int, ARRAY['Instead']::text[], '"Instead" = thay vào đó (tổ chức ngày khác).', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'tu-noi-chen-cau-part-6'), 'error', 'intermediate', 'Sales dropped in May. [[Therefore]], they [[rose]] again [[in]] [[June]].', ARRAY[]::text[], 0::int, ARRAY[]::text[], 'Ý trái chiều → However.', 'mistakes', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'tu-noi-chen-cau-part-6'), 'choice', 'advanced', 'Dear customers, our store will move to a new location next month. ___ We look forward to seeing you there.', ARRAY['The new store will be twice as large as the current one.', 'Our prices have increased recently.', 'Please return the damaged item.', 'The position has been filled.']::text[], 0::int, ARRAY[]::text[], 'Câu chèn phải nói về cửa hàng mới, nối với "there" ở câu sau.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'tu-noi-chen-cau-part-6'), 'choice', 'advanced', 'Thank you for your order. ___ You will receive a tracking number by e-mail.', ARRAY['It was shipped this morning.', 'We are hiring sales staff.', 'The meeting was canceled.', 'Please submit your résumé.']::text[], 0::int, ARRAY[]::text[], '"It" = your order; nối mạch với tracking number.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'tu-noi-chen-cau-part-6'), 'choice', 'advanced', 'The training session has been very popular. ___, we have added a second session on Friday.', ARRAY['Nevertheless', 'Consequently', 'Otherwise', 'Meanwhile']::text[], 1::int, ARRAY[]::text[], 'Hệ quả của việc đông người → Consequently.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'tu-noi-chen-cau-part-6'), 'choice', 'advanced', 'The budget is limited. ___, we will try to purchase the equipment.', ARRAY['Therefore', 'Nevertheless', 'For instance', 'Moreover']::text[], 1::int, ARRAY[]::text[], 'Dù hạn chế vẫn cố mua → Nevertheless.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'tu-noi-chen-cau-part-6'), 'choice', 'advanced', 'Mr. Lopez will be on leave next week. ___, Ms. Chan will handle his clients.', ARRAY['In the meantime', 'As a result of', 'Even though', 'In contrast']::text[], 0::int, ARRAY[]::text[], 'Trong lúc đó → In the meantime.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'tu-noi-chen-cau-part-6'), 'choice', 'advanced', 'We have updated our refund policy. ___ Please read them carefully before making a purchase.', ARRAY['The changes take effect on June 1.', 'Our staff are friendly.', 'The store opens at 9 a.m.', 'We have many branches.']::text[], 0::int, ARRAY[]::text[], '"them" ở câu sau trỏ về "The changes".', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'tu-noi-chen-cau-part-6'), 'fill', 'advanced', 'The software update fixes several bugs. ___ (Moreover/However), it improves battery life.', ARRAY[]::text[], NULL::int, ARRAY['Moreover']::text[], 'Thêm ý cùng chiều → Moreover.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'tu-noi-chen-cau-part-6'), 'fill', 'advanced', 'Attendance was lower than expected. ___ (Nevertheless/Therefore), the event raised a lot of money.', ARRAY[]::text[], NULL::int, ARRAY['Nevertheless']::text[], 'Tương phản → Nevertheless.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'tu-noi-chen-cau-part-6'), 'error', 'advanced', 'The [[factory]] cut its energy use. [[For example]], its [[costs]] [[fell]] sharply.', ARRAY[]::text[], 1::int, ARRAY[]::text[], 'Hệ quả → As a result.', 'mistakes', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'tu-noi-chen-cau-part-6'), 'error', 'advanced', 'The [[product]] is [[affordable]]. [[However]], it is also [[durable]].', ARRAY[]::text[], 2::int, ARRAY[]::text[], 'Hai ý cùng chiều tích cực → Moreover / In addition.', 'mistakes', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'tu-noi-chen-cau-part-6'), 'choice', 'advanced', 'Our team will be at the trade show in Berlin. ___, our office will remain open as usual.', ARRAY['Meanwhile', 'Therefore', 'For example', 'Likewise']::text[], 0::int, ARRAY[]::text[], 'Đồng thời → Meanwhile.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'tu-noi-chen-cau-part-6'), 'choice', 'advanced', 'Ms. Diaz has twenty years of experience. ___, she has led three successful mergers.', ARRAY['Furthermore', 'Instead', 'Otherwise', 'Nonetheless']::text[], 0::int, ARRAY[]::text[], 'Bổ sung → Furthermore.', 'structure', now()),
  ((SELECT "id" FROM "grammar_topics" WHERE "slug" = 'tu-noi-chen-cau-part-6'), 'choice', 'advanced', 'Your subscription expires on May 31. ___ To continue your service, please renew online.', ARRAY['After that date, you will lose access to premium content.', 'Our office is closed on weekends.', 'The magazine was founded in 1990.', 'We have hired a new editor.']::text[], 0::int, ARRAY[]::text[], 'Câu chèn nối "expires" với lời mời gia hạn.', 'structure', now())
